  // -------------------- CHUNK / ROAD GENERATION --------------------
  roadCurveX(z){
    // layered sine curve producing winding road; parameters vary slowly with z
    const f1=0.0021, f2=0.0006, f3=0.00037;
    let x = Math.sin(z*f1+13.1)*7 + Math.sin(z*f2+4.2)*13 + Math.sin(z*f3)*5;
    return x;
  }
  roadCurveY(z){
    const f1=0.0017, f2=0.0005;
    return Math.sin(z*f1+2.0)*3.2 + Math.sin(z*f2+8.0)*2.0;
  }
  roadWidthAt(z){ return CFG.ROAD_WIDTH; }
  // fork handling: returns {active,branchOffsetFn} describing extra lateral offset at z
  isForkZoneAt(z){
    const idx = Math.floor(z/CFG.FORK_SPACING);
    if(idx<1) return null;
    const zoneStart = idx*CFG.FORK_SPACING;
    const zoneEnd = zoneStart+CFG.FORK_ZONE_LEN;
    if(z>=zoneStart && z<zoneEnd) return { idx, zoneStart, zoneEnd, local:z-zoneStart };
    return null;
  }
  forkBranchOffset(zone, side){
    // side: -1 left, 1 right. Ramps out to +-separation then merges back at the end.
    const sep = 9;
    const t = zone.local/CFG.FORK_ZONE_LEN;
    const shape = Math.sin(Math.PI*clamp(t,0,1)); // 0 at ends, 1 in middle
    return side*sep*shape;
  }
  getRoadCenter(z){
    let x = this.roadCurveX(z);
    const y = this.roadCurveY(z);
    const zone = this.isForkZoneAt(z);
    if(zone){
      let side = 0;
      if(zone.idx===this.lastForkChoiceIdx) side=this.lastForkChoiceSide;
      else if(zone.local < CFG.FORK_DECIDE_AT){
        side = 0; // not yet decided, show as merging split (handled in mesh building separately)
      } else {
        // lock-in moment: decide based on current player lateral position relative to center
        side = (this.player.x - this.roadCurveX(zone.zoneStart)) < 0 ? -1 : 1;
        this.lastForkChoiceIdx = zone.idx; this.lastForkChoiceSide = side;
      }
      x += this.forkBranchOffset(zone, side);
    }
    return { x, y };
  }

  makeChunk(startZ){
    const endZ = startZ+CFG.CHUNK_LEN;
    const group = new THREE.Group();
    const segs = CFG.CHUNK_SEGS;
    const zone = this.isForkZoneAt(startZ) || this.isForkZoneAt(endZ);
    const splitVisual = zone && zone.local < CFG.FORK_DECIDE_AT+40;

    const biome = stageAt((startZ+endZ)/2).biome;

    // --- road ribbon mesh (one or two if split) ---
    const roadMat = new THREE.MeshStandardMaterial({ color: biome==='city'?0x25202e:0x2b2b33, roughness:0.75, metalness:0.15 });
    const buildRibbon = (xOffsetFn)=>{
      const geo = new THREE.PlaneGeometry(CFG.ROAD_WIDTH, CFG.CHUNK_LEN, 1, segs);
      geo.rotateX(-Math.PI/2);
      const pos = geo.attributes.position;
      for(let i=0;i<pos.count;i++){
        const lz = pos.getZ(i); // -len/2..len/2 local before offset applied (plane along z before rotate... after rotateX, use Y? )
      }
      // After rotateX(-PI/2): plane originally in XY now lies in XZ; local coordinates: x stays x, former y -> z
      const arr = pos.array;
      for(let i=0;i<pos.count;i++){
        const lx = arr[i*3], lz = arr[i*3+2];
        const worldZ = startZ + CFG.CHUNK_LEN/2 + lz;
        const c = xOffsetFn(worldZ);
        arr[i*3] = lx + c.x;
        arr[i*3+1] = c.y + 0.02;
      }
      geo.computeVertexNormals();
      const mesh = new THREE.Mesh(geo, roadMat);
      mesh.receiveShadow = true;
      mesh.position.z = -(startZ+CFG.CHUNK_LEN/2); // will be offset by group below; actually keep group at origin, use world coords directly
      mesh.position.z = 0;
      return mesh;
    };
    const centerFn = (z)=>this.getRoadCenter(z);
    const roadMesh = buildRibbon(centerFn);
    group.add(roadMesh);

    // lane stripes (emissive thin boxes following centerline) - simple decorative strip via plane w/ dashed texture skipped for perf; use thin emissive line mesh
    const stripeMat = new THREE.MeshStandardMaterial({ color:0xffe27a, emissive:0xffe27a, emissiveIntensity: biome==='city'||biome==='mountain'?1.6:0.6 });
    for(let i=0;i<segs;i++){
      const z0 = startZ + i*(CFG.CHUNK_LEN/segs) + (CFG.CHUNK_LEN/segs)*0.2;
      if(Math.floor(z0/6)%2===0) continue;
      const c = centerFn(z0);
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.03, (CFG.CHUNK_LEN/segs)*0.55), stripeMat);
      stripe.position.set(c.x, c.y+0.04, z0);
      group.add(stripe);
    }

    // --- ground / terrain plane beside road (biome colored) ---
    const groundColors = { beach:0xe8d9a8, desert:0xd9a náo:0 }; // placeholder removed below
    const groundColorMap = { beach:0xe3d2a0, desert:0xcf9a5f, city:0x191420, mountain:0x3a4a3e };
    const groundMat = new THREE.MeshStandardMaterial({ color: groundColorMap[biome]||0x3a4a3e, roughness:1.0 });
    const groundGeo = new THREE.PlaneGeometry(260, CFG.CHUNK_LEN, 1, segs);
    groundGeo.rotateX(-Math.PI/2);
    {
      const pos=groundGeo.attributes.position; const arr=pos.array;
      for(let i=0;i<pos.count;i++){
        const lz=arr[i*3+2];
        const worldZ = startZ+CFG.CHUNK_LEN/2+lz;
        const c=centerFn(worldZ);
        arr[i*3+1]=c.y-0.05;
      }
      groundGeo.computeVertexNormals();
    }
    const groundMesh = new THREE.Mesh(groundGeo, groundMat);
    groundMesh.receiveShadow=true;
    group.add(groundMesh);

    // --- guardrails on sharp curve outsides (simple heuristic: always place sparse rails for safety feel) ---
    const propRefs=[];
    const placeProp = (pool, worldX, worldZ, worldY, rotY, scale)=>{
      const idx = pool.alloc();
      if(idx<0) return;
      pool.set(idx, new THREE.Vector3(worldX,worldY,worldZ), rotY, scale);
      propRefs.push({pool,idx});
    };
    const railEvery = 10;
    for(let z=startZ; z<endZ; z+=railEvery){
      const c=centerFn(z);
      const w = CFG.ROAD_WIDTH/2+0.3;
      placeProp(this.propPools.post, c.x-w, z, c.y, 0, 1);
      placeProp(this.propPools.post, c.x+w, z, c.y, 0, 1);
    }

    // --- biome props (roadside scenery), density based ---
    const propSpacing = 14;
    for(let z=startZ; z<endZ; z+=propSpacing){
      if(srand()>0.55) continue;
      const c=centerFn(z);
      const side = srand()>0.5?1:-1;
      const dist = CFG.ROAD_WIDTH/2 + 3 + srand()*14;
      const px=c.x+side*dist, pz=z+srange(-3,3);
      const py=c.y;
      if(biome==='beach'){
        if(srand()>0.6) placeProp(this.propPools.palm, px, pz, py, srand()*Math.PI*2, 0.8+srand()*0.5);
        else if(srand()>0.5) placeProp(this.propPools.umbrella, px, pz, py, srand()*Math.PI*2, 0.8+srand()*0.3);
      } else if(biome==='desert'){
        if(srand()>0.5) placeProp(this.propPools.cactus, px, pz, py, srand()*Math.PI*2, 0.7+srand()*0.6);
        else placeProp(this.propPools.rock, px, pz, py, srand()*Math.PI*2, 0.6+srand()*0.8);
      } else if(biome==='city'){
        const h=2+srand()*7;
        const idx=this.buildingPool.alloc();
        if(idx>=0){ this.buildingPool.set(idx, new THREE.Vector3(px, py+h/2, pz), srand()*Math.PI*2, 1);
          this.buildingPool.mesh.setMatrixAt(idx, new THREE.Matrix4().compose(
            new THREE.Vector3(px,py+h/2,pz), new THREE.Quaternion().setFromEuler(new THREE.Euler(0,srand()*Math.PI*2,0)), new THREE.Vector3(3+srand()*2,h,3+srand()*2)
          ));
          this.buildingPool.mesh.instanceMatrix.needsUpdate=true;
          propRefs.push({pool:this.buildingPool, idx});
        }
      } else if(biome==='mountain'){
        placeProp(this.propPools.rock, px, pz, py, srand()*Math.PI*2, 1.0+srand()*1.4);
      }
      if(srand()>0.85) placeProp(this.propPools.sign, c.x+side*(CFG.ROAD_WIDTH/2+1.2), z, c.y, side>0?Math.PI/2:-Math.PI/2, 1);
    }

    this.worldGroup.add(group);
    return { startZ, endZ, group, propRefs, biome };
  }
  destroyChunk(ch){
    for(const {pool,idx} of ch.propRefs) pool.free_(idx);
    this.worldGroup.remove(ch.group);
    ch.group.traverse(o=>{ if(o.geometry) o.geometry.dispose(); });
  }
  fillChunksAhead(instant){
    const chunksAhead = QUALITY[this.quality].chunks;
    const targetZ = this.player.z + chunksAhead*CFG.CHUNK_LEN;
    while(this.nextChunkZ < targetZ){
      RNG_STATE = Math.floor(this.nextChunkZ*7919)>>>0;
      this.chunks.push(this.makeChunk(this.nextChunkZ));
      this.nextChunkZ += CFG.CHUNK_LEN;
    }
    // recycle behind
    while(this.chunks.length && this.chunks[0].endZ < this.player.z - CFG.CHUNK_LEN*3){
      this.destroyChunk(this.chunks.shift());
    }
  }

