    $('btn-retry').onclick=()=>{ Audio_.playStation(this.selectedStation); this.startGame(); };
    $('btn-gameover-title').onclick=()=>{ showScreen('title'); this.state='title'; };
    $('btn-hs-submit').onclick=()=>this.submitHighscore();

    $('vol-master').oninput=e=>Audio_.setVol('master', e.target.value/100);
    $('vol-music').oninput=e=>Audio_.setVol('music', e.target.value/100);
    $('vol-sfx').oninput=e=>Audio_.setVol('sfx', e.target.value/100);
    document.querySelectorAll('[data-q]').forEach(btn=>{
      btn.onclick=()=>{ this.setQuality(btn.dataset.q); document.querySelectorAll('[data-q]').forEach(b=>b.style.borderColor=''); btn.style.borderColor='var(--cyan)'; };
    });

    this.setupTouchControls();
