// ============================================================================
// NEON PURSUIT — main game module
// Sections: CONFIG, UTIL, AUDIO, INPUT, POOLS, MODELS, ROAD, SKY, VEHICLES,
//           WEAPONS, PARTICLES, GAMEPLAY, HUD, UI, MAIN
// ============================================================================
import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { FilmPass } from 'three/addons/postprocessing/FilmPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

// ============================================================================
// CONFIG — tweak these to change difficulty, speed, visuals
// ============================================================================
const CFG = {
  ROAD_WIDTH: 14,
  LANE_W: 3.4,
  CHUNK_LEN: 40,
  CHUNK_SEGS: 6,
  DRAW_CHUNKS: { low: 16, medium: 24, high: 34 },
  MAX_SPEED: 68,          // m/s top speed, no nitro
  NITRO_MAX_SPEED: 102,
  ACCEL: 26,
  BRAKE: 48,
  REVERSE_ACCEL: 14,
  DRAG: 0.993,
  OFFROAD_DRAG: 0.965,
  STEER_RATE: 2.6,        // rad/s of wheel angle change
  MAX_STEER: 0.55,
  GRIP: 9.0,
  DRIFT_GRIP: 3.2,
  DRIFT_SLIP_THRESHOLD: 0.14,
  NITRO_DURATION: 3.2,
  NITRO_REGEN_TIME: 9,
  GUN_COOLDOWN: 0.09,
  GUN_RANGE: 140,
  MISSILE_COOLDOWN: 0.5,
  MISSILE_DAMAGE: 60,
  BULLET_DAMAGE: 9,
  CIVILIAN_HIT_PENALTY_SCORE: -400,
  CIVILIAN_HIT_PENALTY_TIME: -6,
  CHECKPOINT_TIME: 14,
  CHECKPOINT_SPACING: 260,
  TIME_START: 72,
  PLAYER_MAX_HEALTH: 100,
  FORK_SPACING: 1400,
  FORK_ZONE_LEN: 420,
  FORK_DECIDE_AT: 60,      // distance into zone where branch locks
  ENEMY_BASE_DENSITY: 0.009,  // enemies per meter, scales with distance
  CIVILIAN_BASE_DENSITY: 0.015,
  PICKUP_SPACING: 520,
};

const QUALITY = {
  low:    { shadows:false, bloom:0.55, particleMul:0.4, chunks:CFG.DRAW_CHUNKS.low,    pixelRatio:1.0, film:false },
  medium: { shadows:true,  bloom:0.8,  particleMul:0.8, chunks:CFG.DRAW_CHUNKS.medium, pixelRatio:1.3, film:true },
  high:   { shadows:true,  bloom:1.1,  particleMul:1.3, chunks:CFG.DRAW_CHUNKS.high,   pixelRatio:1.8, film:true },
};

// Biome stage list (meters where each begins), cycles after the last
const STAGES = [
  { name:'COASTAL HIGHWAY', biome:'beach',   sky:'day',    len:1600 },
  { name:'SUNSET DUNES',    biome:'desert',  sky:'sunset', len:1700 },
  { name:'MIDNIGHT CITY',   biome:'city',    sky:'night',  len:1800 },
  { name:'DUSK PASS',       biome:'mountain',sky:'dusk',   len:1700 },
];
const STAGE_TOTAL_LEN = STAGES.reduce((a,s)=>a+s.len,0);

const SKY_PALETTES = {
  day:   { top:0x1b6fd6, bottom:0xbfe9ff, fog:0x9fd3f2, sun:0xfff3c4, hemiSky:0xbfe9ff, hemiGround:0x3a6b3a, dirColor:0xfff6e0, dirInt:1.6, ambient:0.55, stars:0, sunY:0.62 },
  sunset:{ top:0x3b1458, bottom:0xff7a3d, fog:0xff9a62, sun:0xffd23f, hemiSky:0xff9a62, hemiGround:0x5a3a2a, dirColor:0xffb36b, dirInt:1.25, ambient:0.45, stars:0.3, sunY:0.22 },
  dusk:  { top:0x140826, bottom:0x5a2a6b, fog:0x3a1f4a, sun:0xff6b9a, hemiSky:0x5a2a6b, hemiGround:0x241433, dirColor:0xb87bff, dirInt:0.8, ambient:0.35, stars:0.7, sunY:0.1 },
  night: { top:0x05030e, bottom:0x160a2e, fog:0x0c0620, sun:0x8b2fff, hemiSky:0x1a0f33, hemiGround:0x0a0614, dirColor:0x6b8bff, dirInt:0.35, ambient:0.22, stars:1.0, sunY:-0.1 },
};

// ============================================================================
// UTIL
// ============================================================================
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lerp=(a,b,t)=>a+(b-a)*t;
const smoothstep=(a,b,t)=>{t=clamp((t-a)/(b-a),0,1);return t*t*(3-2*t);};
function rand(seed){ // simple deterministic PRNG (mulberry32), seed is a number
  let t = seed + 0x6D2B79F5;
  t = Math.imul(t ^ (t>>>15), t | 1);
  t ^= t + Math.imul(t ^ (t>>>7), t | 61);
  return ((t ^ (t>>>14)) >>> 0) / 4294967296;
}
let RNG_STATE = 12345;
function srand(){ RNG_STATE = (RNG_STATE*1664525+1013904223) >>> 0; return RNG_STATE/4294967296; }
function srange(a,b){ return a+(b-a)*srand(); }
function pick(arr){ return arr[Math.floor(srand()*arr.length)%arr.length]; }

function stageAt(distance){
  let d = ((distance % STAGE_TOTAL_LEN)+STAGE_TOTAL_LEN) % STAGE_TOTAL_LEN;
  for(const s of STAGES){ if(d < s.len) return s; d -= s.len; }
  return STAGES[0];
}
function stageBlend(distance){
  // returns {a,b,t} interpolation between consecutive stage sky palettes for smooth transitions
  let d = ((distance % STAGE_TOTAL_LEN)+STAGE_TOTAL_LEN) % STAGE_TOTAL_LEN;
  let i=0;
  for(;i<STAGES.length;i++){ if(d < STAGES[i].len) break; d -= STAGES[i].len; }
  const cur = STAGES[i % STAGES.length];
  const next = STAGES[(i+1) % STAGES.length];
  const transition = 220;
  const t = d > cur.len - transition ? smoothstep(cur.len-transition, cur.len, d) : 0;
  return { a:cur.sky, b:next.sky, t, biome:cur.biome, name:cur.name };
}

// ============================================================================
// AUDIO — procedural Web Audio engine
// ============================================================================
const Audio_ = (()=>{
  let ctx=null, master, musicGain, sfxGain, engineGain;
  let started=false;
  let engineNodes=null;
  let musicState=null;
  const stations = [
    { name:'OUTRUN 85', desc:'Bassline + arps, classic cruise', key:'a' },
    { name:'NEON PULSE', desc:'Gated drums, driving energy', key:'b' },
    { name:'VELVET NIGHT', desc:'Slow arpeggio, dusk mood', key:'c' },
  ];
  function init(){
    if(ctx) return;
    ctx = new (window.AudioContext||window.webkitAudioContext)();
    master = ctx.createGain(); master.gain.value=0.8; master.connect(ctx.destination);
    musicGain = ctx.createGain(); musicGain.gain.value=0.6; musicGain.connect(master);
    sfxGain = ctx.createGain(); sfxGain.gain.value=0.9; sfxGain.connect(master);
    engineGain = ctx.createGain(); engineGain.gain.value=0.5; engineGain.connect(sfxGain);
  }
  function resume(){ if(ctx && ctx.state==='suspended') ctx.resume(); started=true; }
  function setVol(which,v){
    if(!ctx) return;
    if(which==='master') master.gain.setTargetAtTime(v,ctx.currentTime,0.05);
    if(which==='music') musicGain.gain.setTargetAtTime(v,ctx.currentTime,0.05);
    if(which==='sfx') sfxGain.gain.setTargetAtTime(v,ctx.currentTime,0.05);
  }
  function noiseBuffer(dur=1){
    const n = ctx.sampleRate*dur;
    const buf = ctx.createBuffer(1,n,ctx.sampleRate);
    const d = buf.getChannelData(0);
    for(let i=0;i<n;i++) d[i]=Math.random()*2-1;
    return buf;
  }
  let noiseBuf1s=null;
  function getNoise(){ if(!noiseBuf1s) noiseBuf1s=noiseBuffer(1); return noiseBuf1s; }

  // ---- SFX ----
  function sfxGunshot(){
    if(!ctx) return;
    const t=ctx.currentTime;
    const osc=ctx.createOscillator(); osc.type='square'; osc.frequency.setValueAtTime(220,t);
    osc.frequency.exponentialRampToValueAtTime(60,t+0.07);
    const g=ctx.createGain(); g.gain.setValueAtTime(0.25,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.08);
    const src=ctx.createBufferSource(); src.buffer=getNoise();
    const nf=ctx.createBiquadFilter(); nf.type='highpass'; nf.frequency.value=800;
    const ng=ctx.createGain(); ng.gain.setValueAtTime(0.18,t); ng.gain.exponentialRampToValueAtTime(0.001,t+0.05);
    osc.connect(g).connect(sfxGain); src.connect(nf).connect(ng).connect(sfxGain);
    osc.start(t); osc.stop(t+0.1); src.start(t); src.stop(t+0.06);
  }
  function sfxMissile(){
    if(!ctx) return;
    const t=ctx.currentTime;
    const osc=ctx.createOscillator(); osc.type='sawtooth'; osc.frequency.setValueAtTime(90,t);
    osc.frequency.exponentialRampToValueAtTime(400,t+0.4);
    const g=ctx.createGain(); g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(0.22,t+0.05); g.gain.exponentialRampToValueAtTime(0.001,t+0.5);
    osc.connect(g).connect(sfxGain); osc.start(t); osc.stop(t+0.5);
  }
  function sfxExplosion(big=false){
    if(!ctx) return;
    const t=ctx.currentTime; const dur=big?1.4:0.7;
    const src=ctx.createBufferSource(); src.buffer=getNoise(); src.loop=true;
    const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.setValueAtTime(big?1800:1100,t); f.frequency.exponentialRampToValueAtTime(60,t+dur);
    const g=ctx.createGain(); g.gain.setValueAtTime(big?0.5:0.32,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
    src.connect(f).connect(g).connect(sfxGain);
    src.start(t); src.stop(t+dur);
    duckMusic(dur);
  }
  function sfxCrash(){
    if(!ctx) return;
    const t=ctx.currentTime;
    const src=ctx.createBufferSource(); src.buffer=getNoise();
    const f=ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=500; f.Q.value=0.6;
    const g=ctx.createGain(); g.gain.setValueAtTime(0.4,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.3);
    src.connect(f).connect(g).connect(sfxGain); src.start(t); src.stop(t+0.3);
  }
  function sfxScreech(){
    if(!ctx) return;
    const t=ctx.currentTime;
    const osc=ctx.createOscillator(); osc.type='sawtooth'; osc.frequency.setValueAtTime(900+Math.random()*200,t);
    const f=ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=1800; f.Q.value=6;
    const g=ctx.createGain(); g.gain.setValueAtTime(0.09,t); g.gain.linearRampToValueAtTime(0.0,t+0.25);
    osc.connect(f).connect(g).connect(sfxGain); osc.start(t); osc.stop(t+0.25);
  }
  function sfxChime(){
    if(!ctx) return;
    const t=ctx.currentTime;
    [660,880,1320].forEach((f,i)=>{
      const osc=ctx.createOscillator(); osc.type='sine'; osc.frequency.value=f;
      const g=ctx.createGain(); g.gain.setValueAtTime(0.0001,t+i*0.05); g.gain.exponentialRampToValueAtTime(0.16,t+i*0.05+0.02); g.gain.exponentialRampToValueAtTime(0.001,t+i*0.05+0.3);
      osc.connect(g).connect(sfxGain); osc.start(t+i*0.05); osc.stop(t+i*0.05+0.32);
    });
  }
  function sfxBeepWarn(){
    if(!ctx) return;
    const t=ctx.currentTime;
    const osc=ctx.createOscillator(); osc.type='square'; osc.frequency.value=1000;
    const g=ctx.createGain(); g.gain.setValueAtTime(0.12,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.12);
    osc.connect(g).connect(sfxGain); osc.start(t); osc.stop(t+0.12);
  }
  function sfxPickup(){
    if(!ctx) return;
    const t=ctx.currentTime;
    const osc=ctx.createOscillator(); osc.type='triangle'; osc.frequency.setValueAtTime(400,t);
    osc.frequency.exponentialRampToValueAtTime(1100,t+0.18);
    const g=ctx.createGain(); g.gain.setValueAtTime(0.2,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.2);
    osc.connect(g).connect(sfxGain); osc.start(t); osc.stop(t+0.2);
  }
  let heliNodes=null;
  function heliStart(){
    if(!ctx || heliNodes) return;
    const osc=ctx.createOscillator(); osc.type='square'; osc.frequency.value=28;
    const g=ctx.createGain(); g.gain.value=0.0;
    osc.connect(g).connect(sfxGain); osc.start();
    heliNodes={osc,g};
  }
  function heliSet(vol){ if(heliNodes) heliNodes.g.gain.setTargetAtTime(vol,ctx.currentTime,0.1); }
  function heliStop(){ if(heliNodes){ heliNodes.osc.stop(); heliNodes=null; } }

  let duckTimeout=null;
  function duckMusic(dur){
    if(!ctx) return;
    musicGain.gain.cancelScheduledValues(ctx.currentTime);
    musicGain.gain.setTargetAtTime(0.15,ctx.currentTime,0.05);
    clearTimeout(duckTimeout);
    duckTimeout=setTimeout(()=>{ musicGain.gain.setTargetAtTime(musicBaseVol,ctx.currentTime,0.4); }, dur*1000*0.6);
  }
  let musicBaseVol=0.6;

  // ---- Engine sound: layered oscillators tracking RPM ----
  function engineInit(){
    if(!ctx || engineNodes) return;
    const osc1=ctx.createOscillator(); osc1.type='sawtooth';
    const osc2=ctx.createOscillator(); osc2.type='square';
    const sub=ctx.createOscillator(); sub.type='sine';
    const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=900;
    const g1=ctx.createGain(); g1.gain.value=0.07;
    const g2=ctx.createGain(); g2.gain.value=0.035;
    const gs=ctx.createGain(); gs.gain.value=0.05;
    osc1.connect(g1).connect(f); osc2.connect(g2).connect(f); sub.connect(gs).connect(f);
    f.connect(engineGain);
    osc1.start(); osc2.start(); sub.start();
    engineNodes={osc1,osc2,sub,f,g1,g2,gs,gear:1,lastShift:0};
  }
  function engineUpdate(throttle01, speed01, dt, nowSec){
    if(!engineNodes) return;
    const n=engineNodes;
    // simulated gear shifts: rpm within gear 0..1 maps speed ranges
    const gearCount=5;
    let gearSpeed = speed01*gearCount;
    let gear = Math.min(gearCount-1, Math.floor(gearSpeed));
    let rpm = gearSpeed - gear; // 0..1 within gear
    if(gear !== n.gear && nowSec - n.lastShift > 0.15){
      n.lastShift = nowSec; n.gear = gear;
    }
    const baseFreq = 55 + rpm*90 + gear*18;
    const targetFreq = baseFreq * (0.5+throttle01*0.5+0.5);
    n.osc1.frequency.setTargetAtTime(targetFreq, ctx.currentTime, 0.03);
    n.osc2.frequency.setTargetAtTime(targetFreq*2.01, ctx.currentTime, 0.03);
    n.sub.frequency.setTargetAtTime(targetFreq*0.5, ctx.currentTime, 0.03);
    n.f.frequency.setTargetAtTime(500+rpm*2200+throttle01*600, ctx.currentTime,0.05);
    const vol = 0.4+throttle01*0.5;
    engineGain.gain.setTargetAtTime(vol, ctx.currentTime, 0.08);
  }

  // ---- Music: 3 stations, generated with simple step sequencers ----
  function stopMusic(){
    if(musicState){ musicState.stop=true; }
    musicState=null;
  }
  function scheduleStep(fn, stepTime, steps, startAt){
    let i=0;
    const state={stop:false};
    function tick(){
      if(state.stop) return;
      fn(i%steps, ctx.currentTime);
      i++;
      const id=setTimeout(tick, stepTime*1000);
      state._id=id;
    }
    tick();
    return state;
  }
  function playNote(freq,t,dur,type,vol,filterFreq){
    const osc=ctx.createOscillator(); osc.type=type; osc.frequency.value=freq;
    const g=ctx.createGain(); g.gain.setValueAtTime(0.0001,t);
    g.gain.exponentialRampToValueAtTime(vol,t+0.01);
    g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    let node=osc;
    if(filterFreq){ const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=filterFreq; osc.connect(f); node=f; }
    node.connect(g).connect(musicGain);
    osc.start(t); osc.stop(t+dur+0.02);
  }
  function playDrum(kind,t){
    if(kind==='kick'){
      const osc=ctx.createOscillator(); osc.type='sine'; osc.frequency.setValueAtTime(130,t); osc.frequency.exponentialRampToValueAtTime(40,t+0.12);
      const g=ctx.createGain(); g.gain.setValueAtTime(0.45,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.18);
      osc.connect(g).connect(musicGain); osc.start(t); osc.stop(t+0.2);
    } else if(kind==='snare'){
      const src=ctx.createBufferSource(); src.buffer=getNoise();
      const f=ctx.createBiquadFilter(); f.type='highpass'; f.frequency.value=1200;
      const g=ctx.createGain(); g.gain.setValueAtTime(0.22,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.12);
      src.connect(f).connect(g).connect(musicGain); src.start(t); src.stop(t+0.12);
    } else if(kind==='hat'){
      const src=ctx.createBufferSource(); src.buffer=getNoise();
      const f=ctx.createBiquadFilter(); f.type='highpass'; f.frequency.value=6000;
      const g=ctx.createGain(); g.gain.setValueAtTime(0.08,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.04);
      src.connect(f).connect(g).connect(musicGain); src.start(t); src.stop(t+0.05);
    }
  }
  const SCALE_MIN = [220,246.94,261.63,293.66,329.63,349.23,392.00,440]; // A minor-ish
  function startStationA(){ // OUTRUN 85 — bassline + arp, mid tempo
    const bpm=118, step=60/bpm/2;
    const bass=[0,0,3,3,4,4,2,2];
    const arp=[0,4,5,7,5,4,0,2];
    musicState = scheduleStep((i,t)=>{
      playNote(SCALE_MIN[bass[i%8]]/2, t, step*1.9, 'sawtooth', 0.11, 500);
      playNote(SCALE_MIN[arp[i%8]], t+step*0.5, step*0.5, 'square', 0.05, 2200);
      if(i%4===0) playDrum('kick',t);
      if(i%8===4) playDrum('snare',t);
      if(i%2===0) playDrum('hat',t);
    }, step, 8);
  }
  function startStationB(){ // NEON PULSE — gated drums, driving
    const bpm=132, step=60/bpm/2;
    const bass=[0,2,0,2,3,2,0,5];
    musicState = scheduleStep((i,t)=>{
      playNote(SCALE_MIN[bass[i%8]]/2, t, step*0.9, 'square', 0.1, 700);
      if(i%2===0) playDrum('kick',t);
      playDrum('hat',t);
      if(i%8===6) playDrum('snare',t);
      if(i%16===0) playNote(SCALE_MIN[7], t, step*4, 'sawtooth', 0.06, 1400);
    }, step, 16);
  }
  function startStationC(){ // VELVET NIGHT — slow arpeggio, dusk mood
    const bpm=86, step=60/bpm/2;
    const arp=[0,3,5,7,8,7,5,3];
    musicState = scheduleStep((i,t)=>{
      playNote(SCALE_MIN[arp[i%8]], t, step*1.6, 'triangle', 0.09, 1800);
      if(i%8===0) playNote(SCALE_MIN[0]/2, t, step*6, 'sine', 0.08, 400);
      if(i%4===0) playDrum('hat',t);
    }, step, 8);
  }
  function playStation(idx){
    stopMusic();
    if(!ctx) return;
    if(idx===0) startStationA();
    else if(idx===1) startStationB();
    else startStationC();
  }
  return {
    init, resume, setVol, stations, playStation, stopMusic,
    sfxGunshot, sfxMissile, sfxExplosion, sfxCrash, sfxScreech, sfxChime, sfxBeepWarn, sfxPickup,
    heliStart, heliSet, heliStop, engineInit, engineUpdate,
    get ctx(){ return ctx; }
  };
})();

