function mergeColored(parts){
  // parts: [{geo, color}] -> merged BufferGeometry with vertex colors
  const geos=[];
  for(const p of parts){
    const g = p.geo.clone();
    g.applyMatrix4(p.matrix||new THREE.Matrix4());
    const count = g.attributes.position.count;
    const colors = new Float32Array(count*3);
    const c = new THREE.Color(p.color);
    for(let i=0;i<count;i++){ colors[i*3]=c.r; colors[i*3+1]=c.g; colors[i*3+2]=c.b; }
    g.setAttribute('color', new THREE.BufferAttribute(colors,3));
    geos.push(g);
  }
  return mergeGeometries(geos,false);
}
const mat4=(x=0,y=0,z=0,rx=0,ry=0,rz=0,sx=1,sy=1,sz=1)=>{
  const m=new THREE.Matrix4();
  const q=new THREE.Quaternion().setFromEuler(new THREE.Euler(rx,ry,rz));
  m.compose(new THREE.Vector3(x,y,z), q, new THREE.Vector3(sx,sy,sz));
  return m;
};

function buildCarBody(bodyColor, cabinColor){
  const group = new THREE.Group();
  const bodyMat = new THREE.MeshStandardMaterial({ color:bodyColor, metalness:0.5, roughness:0.35 });
  const cabinMat = new THREE.MeshStandardMaterial({ color:cabinColor, metalness:0.2, roughness:0.5, transparent:true, opacity:0.85 });
  const darkMat = new THREE.MeshStandardMaterial({ color:0x111319, metalness:0.3, roughness:0.6 });

  const chassis = new THREE.Mesh(new THREE.BoxGeometry(2.0,0.45,4.3), bodyMat);
  chassis.position.y=0.5; chassis.castShadow=true; chassis.receiveShadow=true;
  group.add(chassis);

  const hood = new THREE.Mesh(new THREE.BoxGeometry(1.85,0.3,1.5), bodyMat);
  hood.position.set(0,0.68,1.55); hood.castShadow=true;
  group.add(hood);

  const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.7,0.5,1.6), cabinMat);
  cabin.position.set(0,0.95,-0.2); cabin.castShadow=true;
  group.add(cabin);

  const trunk = new THREE.Mesh(new THREE.BoxGeometry(1.85,0.32,1.0), bodyMat);
  trunk.position.set(0,0.7,-1.75); trunk.castShadow=true;
  group.add(trunk);

  // driver silhouette
  const driver = new THREE.Mesh(new THREE.CapsuleGeometry(0.22,0.35,4,6), darkMat);
  driver.position.set(-0.4,0.95,-0.1);
  group.add(driver);

  // bumpers
  const bumperF = new THREE.Mesh(new THREE.BoxGeometry(2.05,0.25,0.25), darkMat);
  bumperF.position.set(0,0.42,2.15); group.add(bumperF);
  const bumperR = new THREE.Mesh(new THREE.BoxGeometry(2.05,0.25,0.25), darkMat);
  bumperR.position.set(0,0.42,-2.15); group.add(bumperR);

  // lights
  const headlightMat = new THREE.MeshStandardMaterial({ color:0xffffff, emissive:0xfff6cc, emissiveIntensity:2.2 });
  const taillightMat = new THREE.MeshStandardMaterial({ color:0x550008, emissive:0xff0022, emissiveIntensity:1.6 });
  const hl1=new THREE.Mesh(new THREE.BoxGeometry(0.3,0.15,0.08),headlightMat); hl1.position.set(-0.65,0.55,2.18); group.add(hl1);
  const hl2=hl1.clone(); hl2.position.x=0.65; group.add(hl2);
  const tl1=new THREE.Mesh(new THREE.BoxGeometry(0.35,0.15,0.08),taillightMat); tl1.position.set(-0.65,0.6,-2.18); group.add(tl1);
  const tl2=tl1.clone(); tl2.position.x=0.65; group.add(tl2);

  // headlight spotlights (added only for player / toggled at night by caller)
  group.userData.headlightMeshes=[hl1,hl2];
  group.userData.taillightMeshes=[tl1,tl2];
  group.userData.taillightMat=taillightMat;

  // wheels
