// ---- prop geometries for instancing pools ----
function geoPalmTree(){
  const trunk = new THREE.CylinderGeometry(0.1,0.18,3.2,6);
  trunk.translate(0,1.6,0); trunk.rotateZ(0.08);
  const leafGeos=[];
  for(let i=0;i<5;i++){
    const leaf = new THREE.ConeGeometry(0.9,0.25,5);
    leaf.rotateX(Math.PI/2.3);
    leaf.rotateY(i*(Math.PI*2/5));
    leaf.translate(0,3.3,0);
    leafGeos.push({geo:leaf,color:0x2f8f4e});
  }
  return mergeColored([{geo:trunk,color:0x7a5230}, ...leafGeos]);
}
function geoCactus(){
  const main=new THREE.CylinderGeometry(0.3,0.35,2.2,8); main.translate(0,1.1,0);
  const arm1=new THREE.CylinderGeometry(0.16,0.18,1.0,6); arm1.rotateZ(Math.PI/2.2); arm1.translate(0.45,1.5,0);
  const arm2=new THREE.CylinderGeometry(0.16,0.18,0.9,6); arm2.rotateZ(-Math.PI/2.4); arm2.translate(-0.4,1.9,0);
  return mergeColored([{geo:main,color:0x3f8f5a},{geo:arm1,color:0x3f8f5a},{geo:arm2,color:0x3f8f5a}]);
}
function geoRock(){
  const g = new THREE.IcosahedronGeometry(0.9,0);
  const pos = g.attributes.position;
  for(let i=0;i<pos.count;i++){ pos.setXYZ(i, pos.getX(i)*(0.8+srand()*0.4), pos.getY(i)*(0.6+srand()*0.3), pos.getZ(i)*(0.8+srand()*0.4)); }
  g.computeVertexNormals();
  return mergeColored([{geo:g,color:0x6b6560}]);
}
function geoGuardrailPost(){
  const post=new THREE.BoxGeometry(0.12,1.0,0.12); post.translate(0,0.5,0);
  const rail=new THREE.BoxGeometry(2.0,0.15,0.08); rail.translate(0,0.85,0);
  return mergeColored([{geo:post,color:0x888a90},{geo:rail,color:0xd8d8da}]);
}
function geoRoadSign(){
  const pole=new THREE.CylinderGeometry(0.06,0.06,2.2,6); pole.translate(0,1.1,0);
  const board=new THREE.BoxGeometry(0.9,0.9,0.05); board.translate(0,2.0,0);
  return mergeColored([{geo:pole,color:0xaaaaaa},{geo:board,color:0xffd23f}]);
}
function geoUmbrella(){
  const pole=new THREE.CylinderGeometry(0.04,0.04,1.8,6); pole.translate(0,0.9,0);
  const top=new THREE.ConeGeometry(1.0,0.5,10); top.translate(0,1.85,0);
  return mergeColored([{geo:pole,color:0xeeeeee},{geo:top,color:0xff2e9a}]);
}
function buildingTexture(){
  const c=document.createElement('canvas'); c.width=64; c.height=128;
  const ctx=c.getContext('2d');
  ctx.fillStyle='#1a1430'; ctx.fillRect(0,0,64,128);
  for(let y=6;y<128;y+=12){
    for(let x=4;x<64;x+=10){
      if(srand()>0.4){ ctx.fillStyle = srand()>0.5? '#ffd23f':'#2de2ff'; ctx.globalAlpha=0.8; ctx.fillRect(x,y,5,7); ctx.globalAlpha=1; }
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

