  // -------------------- RENDERER / SCENE --------------------
  initRenderer(){
    this.renderer = new THREE.WebGLRenderer({ canvas:this.canvas, antialias:true, powerPreference:'high-performance' });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  }
  initScene(){
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(62, window.innerWidth/window.innerHeight, 0.1, 900);

    this.hemi = new THREE.HemisphereLight(0xbfe9ff,0x3a6b3a,0.6);
    this.scene.add(this.hemi);
    this.sun = new THREE.DirectionalLight(0xffffff,1.5);
    this.sun.castShadow=true;
    this.sun.shadow.mapSize.set(1024,1024);
    this.sun.shadow.camera.left=-30; this.sun.shadow.camera.right=30;
    this.sun.shadow.camera.top=30; this.sun.shadow.camera.bottom=-30;
    this.sun.shadow.camera.far=120;
    this.sun.shadow.bias=-0.0015;
    this.scene.add(this.sun); this.scene.add(this.sun.target);

    this.scene.fog = new THREE.FogExp2(0x9fd3f2, 0.0032);

    // sky dome
    this.skyMat = new THREE.ShaderMaterial({
      uniforms:{
        topColor:{value:new THREE.Color(0x1b6fd6)},
        bottomColor:{value:new THREE.Color(0xbfe9ff)},
        sunColor:{value:new THREE.Color(0xfff3c4)},
        sunY:{value:0.6}, sunX:{value:0.0},
        starAmount:{value:0.0}, time:{value:0},
      },
      vertexShader:`varying vec3 vPos; void main(){ vPos=normalize(position); gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
      fragmentShader:`
        varying vec3 vPos; uniform vec3 topColor,bottomColor,sunColor; uniform float sunY,sunX,starAmount,time;
        float hash(vec3 p){ return fract(sin(dot(p,vec3(12.9898,78.233,37.719)))*43758.5453); }
        void main(){
          float h = clamp(vPos.y*0.5+0.5,0.0,1.0);
          vec3 col = mix(bottomColor, topColor, pow(h,0.55));
          vec2 sunDir = normalize(vec2(sunX,sunY));
          float d = distance(normalize(vec2(vPos.x,vPos.y)), sunDir);
          float sunDisc = smoothstep(0.17,0.0,d);
          float sunGlow = smoothstep(0.5,0.0,d)*0.5;
          col += sunColor*sunDisc*1.4;
          col += sunColor*sunGlow*0.5;
          // retro horizontal stripes cut into the sun
          float stripe = sin((vPos.y*40.0)+time*0.2);
          float stripeCut = smoothstep(0.0,0.15,stripe);
          col -= sunColor*sunDisc*(1.0-stripeCut)*0.55;
          if(starAmount>0.001 && vPos.y>0.05){
            vec3 cell = floor(vPos*220.0);
            float s = hash(cell);
            float tw = sin(time*2.0+s*50.0)*0.5+0.5;
            float star = step(0.9975,s)*tw*starAmount;
            col += vec3(star);
          }
          gl_FragColor = vec4(col,1.0);
        }
      `,
      side: THREE.BackSide, depthWrite:false,
    });
    this.skyMesh = new THREE.Mesh(new THREE.SphereGeometry(500,24,16), this.skyMat);
    this.scene.add(this.skyMesh);

    // ocean (beach biome)
    const oceanGeo = new THREE.PlaneGeometry(400,400,48,48);
    this.oceanGeo = oceanGeo;
    this.oceanBasePos = oceanGeo.attributes.position.array.slice();
    const oceanMat = new THREE.MeshStandardMaterial({ color:0x1a5fa0, metalness:0.5, roughness:0.25, transparent:true, opacity:0.88 });
    this.ocean = new THREE.Mesh(oceanGeo, oceanMat);
    this.ocean.rotation.x=-Math.PI/2; this.ocean.position.set(-40,-0.3,0);
    this.scene.add(this.ocean);

    this.worldGroup = new THREE.Group();
    this.scene.add(this.worldGroup);

    this.composerSetup();
  }
  composerSetup(){
    this.composer = new EffectComposer(this.renderer);
    const renderPass = new RenderPass(this.scene, this.camera);
    this.composer.addPass(renderPass);
    this.bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth,window.innerHeight), 0.8, 0.5, 0.2);
    this.composer.addPass(this.bloomPass);
    this.filmPass = new FilmPass(0.28, false);
    this.composer.addPass(this.filmPass);
    this.outputPass = new OutputPass();
    this.composer.addPass(this.outputPass);
  }
  initPools(){
    const quality = QUALITY[this.quality];
    this.propPools = {
      palm: new PropPool(geoPalmTree(), new THREE.MeshStandardMaterial({vertexColors:true,roughness:0.8}), 80, this.worldGroup),
      cactus: new PropPool(geoCactus(), new THREE.MeshStandardMaterial({vertexColors:true,roughness:0.9}), 60, this.worldGroup),
      rock: new PropPool(geoRock(), new THREE.MeshStandardMaterial({vertexColors:true,roughness:1.0}), 70, this.worldGroup),
      post: new PropPool(geoGuardrailPost(), new THREE.MeshStandardMaterial({vertexColors:true,metalness:0.3,roughness:0.6}), 160, this.worldGroup),
      sign: new PropPool(geoRoadSign(), new THREE.MeshStandardMaterial({vertexColors:true,roughness:0.6}), 40, this.worldGroup),
      umbrella: new PropPool(geoUmbrella(), new THREE.MeshStandardMaterial({vertexColors:true,roughness:0.7}), 40, this.worldGroup),
