    this.buildingTex = buildingTexture();
    this.buildingMat = new THREE.MeshStandardMaterial({ color:0x2a2244, map:this.buildingTex, emissive:0xffffff, emissiveMap:this.buildingTex, emissiveIntensity:0.0, roughness:0.8 });
    this.buildingPool = new PropPool(new THREE.BoxGeometry(3,1,3), this.buildingMat, 60, this.worldGroup);

    // particle systems
