  // -------------------- CHUNK / ROAD GENERATION --------------------
  roadCurveX(z){
    // layered sine curve producing winding road; parameters vary slowly with z
    const f1=0.0021, f2=0.0006, f3=0.00037;
    let x = Math.sin(z*f1+13.1)*7 + Math.sin(z*f2+4.2)*13 + Math.sin(z*f3)*5;
    return x;
  }
  roadCurveY(z){
    const f1=0.0017, f2=0.0005;
    return Math.sin(z*f1+2.0)*3.2 + Math.sin(z*f2+8.0)*2.0;
  }
  roadWidthAt(z){ return CFG.ROAD_WIDTH; }
  // fork handling: returns {active,branchOffsetFn} describing extra lateral offset at z
  isForkZoneAt(z){
    const idx = Math.floor(z/CFG.FORK_SPACING);
    if(idx<1) return null;
    const zoneStart = idx*CFG.FORK_SPACING;
    const zoneEnd = zoneStart+CFG.FORK_ZONE_LEN;
    if(z>=zoneStart && z<zoneEnd) return { idx, zoneStart, zoneEnd, local:z-zoneStart };
    return null;
  }
  forkBranchOffset(zone, side){
    // side: -1 left, 1 right. Ramps out to +-separation then merges back at the end.
    const sep = 9;
    const t = zone.local/CFG.FORK_ZONE_LEN;
    const shape = Math.sin(Math.PI*clamp(t,0,1)); // 0 at ends, 1 in middle
    return side*sep*shape;
  }
  getRoadCenter(z){
    let x = this.roadCurveX(z);
    const y = this.roadCurveY(z);
    const zone = this.isForkZoneAt(z);
    if(zone){
      let side = 0;
      if(zone.idx===this.lastForkChoiceIdx) side=this.lastForkChoiceSide;
      else if(zone.local < CFG.FORK_DECIDE_AT){
        side = 0; // not yet decided, show as merging split (handled in mesh building separately)
      } else {
        // lock-in moment: decide based on current player lateral position relative to center
        side = (this.player.x - this.roadCurveX(zone.zoneStart)) < 0 ? -1 : 1;
        this.lastForkChoiceIdx = zone.idx; this.lastForkChoiceSide = side;
      }
      x += this.forkBranchOffset(zone, side);
    }
    return { x, y };
  }

  makeChunk(startZ){
    const endZ = startZ+CFG.CHUNK_LEN;
    const group = new THREE.Group();
    const segs = CFG.CHUNK_SEGS;
    const zone = this.isForkZoneAt(startZ) || this.isForkZoneAt(endZ);
    const splitVisual = zone && zone.local < CFG.FORK_DECIDE_AT+40;

    const biome = stageAt((startZ+endZ)/2).biome;

    // --- road ribbon mesh (one or two if split) ---
    const roadMat = new THREE.MeshStandardMaterial({ color: biome==='city'?0x25202e:0x2b2b33, roughness:0.75, metalness:0.15 });
    const buildRibbon = (xOffsetFn)=>{
      const geo = new THREE.PlaneGeometry(CFG.ROAD_WIDTH, CFG.CHUNK_LEN, 1, segs);
      geo.rotateX(-Math.PI/2);
      const pos = geo.attributes.position;
      for(let i=0;i<pos.count;i++){
        const lz = pos.getZ(i); // -len/2..len/2 local before offset applied (plane along z before rotate... after rotateX, use Y? )
      }
      // After rotateX(-PI/2): plane originally in XY now lies in XZ; local coordinates: x stays x, former y -> z
      const arr = pos.array;
      for(let i=0;i<pos.count;i++){
        const lx = arr[i*3], lz = arr[i*3+2];
        const worldZ = startZ + CFG.CHUNK_LEN/2 + lz;
        const c = xOffsetFn(worldZ);
        arr[i*3] = lx + c.x;
        arr[i*3+1] = c.y + 0.02;
      }
      geo.computeVertexNormals();
      const mesh = new THREE.Mesh(geo, roadMat);
      mesh.receiveShadow = true;
      mesh.position.z = -(startZ+CFG.CHUNK_LEN/2); // will be offset by group below; actually keep group at origin, use world coords directly
      mesh.position.z = 0;
      return mesh;
    };
    const centerFn = (z)=>this.getRoadCenter(z);
    const roadMesh = buildRibbon(centerFn);
    group.add(roadMesh);

    // lane stripes (emissive thin boxes following centerline) - simple decorative strip via plane w/ dashed texture skipped for perf; use thin emissive line mesh
    const stripeMat = new THREE.MeshStandardMaterial({ color:0xffe27a, emissive:0xffe27a, emissiveIntensity: biome==='city'||biome==='mountain'?1.6:0.6 });
    for(let i=0;i<segs;i++){
      const z0 = startZ + i*(CFG.CHUNK_LEN/segs) + (CFG.CHUNK_LEN/segs)*0.2;
      if(Math.floor(z0/6)%2===0) continue;
      const c = centerFn(z0);
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.03, (CFG.CHUNK_LEN/segs)*0.55), stripeMat);
      stripe.position.set(c.x, c.y+0.04, z0);
      group.add(stripe);
    }

    // --- ground / terrain plane beside road (biome colored) ---
    const groundColors = { beach:0xe8d9a8, desert:0xd9a náo:0 }; // placeholder removed below
    const groundColorMap = { beach:0xe3d2a0, desert:0xcf9a5f, city:0x191420, mountain:0x3a4a3e };
    const groundMat = new THREE.MeshStandardMaterial({ color: groundColorMap[biome]||0x3a4a3e, roughness:1.0 });
    const groundGeo = new THREE.PlaneGeometry(260, CFG.CHUNK_LEN, 1, segs);
    groundGeo.rotateX(-Math.PI/2);
    {
      const pos=groundGeo.attributes.position; const arr=pos.array;
      for(let i=0;i<pos.count;i++){
        const lz=arr[i*3+2];
        const worldZ = startZ+CFG.CHUNK_LEN/2+lz;
        const c=centerFn(worldZ);
        arr[i*3+1]=c.y-0.05;
      }
      groundGeo.computeVertexNormals();
    }
    const groundMesh = new THREE.Mesh(groundGeo, groundMat);
    groundMesh.receiveShadow=true;
    group.add(groundMesh);

    // --- guardrails on sharp curve outsides (simple heuristic: always place sparse rails for safety feel) ---
    const propRefs=[];
    const placeProp = (pool, worldX, worldZ, worldY, rotY, scale)=>{
      const idx = pool.alloc();
      if(idx<0) return;
      pool.set(idx, new THREE.Vector3(worldX,worldY,worldZ), rotY, scale);
      propRefs.push({pool,idx});
    };
    const railEvery = 10;
    for(let z=startZ; z<endZ; z+=railEvery){
      const c=centerFn(z);
      const w = CFG.ROAD_WIDTH/2+0.3;
      placeProp(this.propPools.post, c.x-w, z, c.y, 0, 1);
      placeProp(this.propPools.post, c.x+w, z, c.y, 0, 1);
    }

    // --- biome props (roadside scenery), density based ---
    const propSpacing = 14;
    for(let z=startZ; z<endZ; z+=propSpacing){
      if(srand()>0.55) continue;
      const c=centerFn(z);
      const side = srand()>0.5?1:-1;
      const dist = CFG.ROAD_WIDTH/2 + 3 + srand()*14;
      const px=c.x+side*dist, pz=z+srange(-3,3);
      const py=c.y;
      if(biome==='beach'){
        if(srand()>0.6) placeProp(this.propPools.palm, px, pz, py, srand()*Math.PI*2, 0.8+srand()*0.5);
        else if(srand()>0.5) placeProp(this.propPools.umbrella, px, pz, py, srand()*Math.PI*2, 0.8+srand()*0.3);
      } else if(biome==='desert'){
        if(srand()>0.5) placeProp(this.propPools.cactus, px, pz, py, srand()*Math.PI*2, 0.7+srand()*0.6);
        else placeProp(this.propPools.rock, px, pz, py, srand()*Math.PI*2, 0.6+srand()*0.8);
      } else if(biome==='city'){
        const h=2+srand()*7;
        const idx=this.buildingPool.alloc();
        if(idx>=0){ this.buildingPool.set(idx, new THREE.Vector3(px, py+h/2, pz), srand()*Math.PI*2, 1);
          this.buildingPool.mesh.setMatrixAt(idx, new THREE.Matrix4().compose(
            new THREE.Vector3(px,py+h/2,pz), new THREE.Quaternion().setFromEuler(new THREE.Euler(0,srand()*Math.PI*2,0)), new THREE.Vector3(3+srand()*2,h,3+srand()*2)
          ));
          this.buildingPool.mesh.instanceMatrix.needsUpdate=true;
          propRefs.push({pool:this.buildingPool, idx});
        }
      } else if(biome==='mountain'){
        placeProp(this.propPools.rock, px, pz, py, srand()*Math.PI*2, 1.0+srand()*1.4);
      }
      if(srand()>0.85) placeProp(this.propPools.sign, c.x+side*(CFG.ROAD_WIDTH/2+1.2), z, c.y, side>0?Math.PI/2:-Math.PI/2, 1);
    }

    this.worldGroup.add(group);
    return { startZ, endZ, group, propRefs, biome };
  }
  destroyChunk(ch){
    for(const {pool,idx} of ch.propRefs) pool.free_(idx);
    this.worldGroup.remove(ch.group);
    ch.group.traverse(o=>{ if(o.geometry) o.geometry.dispose(); });
  }
  fillChunksAhead(instant){
    const chunksAhead = QUALITY[this.quality].chunks;
    const targetZ = this.player.z + chunksAhead*CFG.CHUNK_LEN;
    while(this.nextChunkZ < targetZ){
      RNG_STATE = Math.floor(this.nextChunkZ*7919)>>>0;
      this.chunks.push(this.makeChunk(this.nextChunkZ));
      this.nextChunkZ += CFG.CHUNK_LEN;
    }
    // recycle behind
    while(this.chunks.length && this.chunks[0].endZ < this.player.z - CFG.CHUNK_LEN*3){
      this.destroyChunk(this.chunks.shift());
    }
  }

  // -------------------- UI WIRING --------------------
  initUI(){
    const $ = id=>document.getElementById(id);
    this.el = {
      hudDom: $('hud-dom'), timer:$('timer'), scoreVal:$('score-val'), comboRow:$('combo-row'),
      healthFill:$('health-bar-fill'), healthPct:$('health-pct'), stageName:$('stage-name'),
      chipGun:$('chip-gun'), chipMissile:$('chip-missile'), chipShield:$('chip-shield'),
      nitroFill:$('nitro-bar-fill'), crashFlash:$('crash-flash'), forkPrompt:$('fork-prompt'),
      screens:{ title:$('screen-title'), radio:$('screen-radio'), help:$('screen-help'), settings:$('screen-settings'), pause:$('screen-pause'), gameover:$('screen-gameover') },
    };
    const showScreen=(name)=>{
      for(const k in this.el.screens) this.el.screens[k].hidden = (k!==name);
    };
    this.showScreen=showScreen;

    $('btn-start').onclick=()=>{ Audio_.init(); Audio_.resume(); Audio_.playStation(this.selectedStation); this.startGame(); };
    $('btn-radio').onclick=()=>{ this.renderStationList(); showScreen('radio'); };
    $('btn-help').onclick=()=>showScreen('help');
    $('btn-settings').onclick=()=>{ this.settingsReturnTo='title'; showScreen('settings'); };
    $('btn-radio-back').onclick=()=>showScreen('title');
    $('btn-help-back').onclick=()=>showScreen('title');
    $('btn-settings-back').onclick=()=>showScreen(this.settingsReturnTo||'title');
    $('btn-resume').onclick=()=>this.resumeGame();
    $('btn-pause-settings').onclick=()=>{ this.settingsReturnTo='pause'; showScreen('settings'); };
    $('btn-pause-quit').onclick=()=>{ this.quitToTitle(); };
    $('btn-retry').onclick=()=>{ Audio_.playStation(this.selectedStation); this.startGame(); };
    $('btn-gameover-title').onclick=()=>{ showScreen('title'); this.state='title'; };
    $('btn-hs-submit').onclick=()=>this.submitHighscore();

    $('vol-master').oninput=e=>Audio_.setVol('master', e.target.value/100);
    $('vol-music').oninput=e=>Audio_.setVol('music', e.target.value/100);
    $('vol-sfx').oninput=e=>Audio_.setVol('sfx', e.target.value/100);
    document.querySelectorAll('[data-q]').forEach(btn=>{
      btn.onclick=()=>{ this.setQuality(btn.dataset.q); document.querySelectorAll('[data-q]').forEach(b=>b.style.borderColor=''); btn.style.borderColor='var(--cyan)'; };
    });

    this.setupTouchControls();
  }
  renderStationList(){
    const list = document.getElementById('station-list');
    list.innerHTML='';
    Audio_.stations.forEach((s,i)=>{
      const d=document.createElement('div'); d.className='station'+(i===this.selectedStation?' sel':'');
      d.innerHTML = `<div><div class="station-name">${s.name}</div><div class="station-desc">${s.desc}</div></div><div>${i===this.selectedStation?'&#9654;':''}</div>`;
      d.onclick=()=>{ this.selectedStation=i; this.renderStationList(); if(Audio_.ctx) Audio_.playStation(i); };
      list.appendChild(d);
    });
  }
  setQuality(q){
    this.quality=q;
    this.renderer.shadowMap.enabled = QUALITY[q].shadows;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio||1, QUALITY[q].pixelRatio));
    this.bloomPass.strength = QUALITY[q].bloom;
    this.filmPass.enabled = QUALITY[q].film;
    this.sun.castShadow = QUALITY[q].shadows;
  }
  setupTouchControls(){
    const tc=document.getElementById('touch-controls');
    if('ontouchstart' in window){ tc.classList.add('active'); }
    const steerEl=document.getElementById('tc-steer');
    let steerTouchId=null;
    const steerRect=()=>steerEl.getBoundingClientRect();
    steerEl.addEventListener('touchstart',e=>{ steerTouchId=e.changedTouches[0].identifier; e.preventDefault(); },{passive:false});
    window.addEventListener('touchmove',e=>{
      for(const t of e.changedTouches){
        if(t.identifier===steerTouchId){
          const r=steerRect(); const dx=(t.clientX-(r.left+r.width/2))/(r.width/2);
          Input.touch.steer = clamp(dx,-1,1);
          const nub=document.getElementById('tc-steer-nub');
          nub.style.transform=`translateX(${clamp(dx,-1,1)*34}px)`;
        }
      }
    },{passive:true});
    window.addEventListener('touchend',e=>{
      for(const t of e.changedTouches){ if(t.identifier===steerTouchId){ steerTouchId=null; Input.touch.steer=0; document.getElementById('tc-steer-nub').style.transform=''; } }
    });
    const bindBtn=(id,prop)=>{
      const el=document.getElementById(id);
      el.addEventListener('touchstart',e=>{ Input.touch[prop]=true; e.preventDefault(); },{passive:false});
      el.addEventListener('touchend',e=>{ Input.touch[prop]=false; e.preventDefault(); },{passive:false});
    };
    bindBtn('tc-gas','gas'); bindBtn('tc-brake','brake'); bindBtn('tc-gun','fire');
    bindBtn('tc-nitro','nitro'); bindBtn('tc-oil','oil'); bindBtn('tc-smoke','smoke');
    document.getElementById('tc-pause').addEventListener('touchstart',e=>{ e.preventDefault(); this.togglePause(); });
  }

  // -------------------- GAME FLOW --------------------
  startGame(){
    this.state='playing';
    document.getElementById('hud-dom').hidden=false;
    this.showScreen('__none__');
    this.resetPlayer();
    Audio_.engineInit();
  }
  togglePause(){
    if(this.state==='playing'){ this.state='paused'; this.showScreen('pause'); Audio_.stopMusic(); }
    else if(this.state==='paused'){ this.resumeGame(); }
  }
  resumeGame(){ this.state='playing'; this.showScreen('__none__'); Audio_.playStation(this.selectedStation); }
  quitToTitle(){ this.state='title'; document.getElementById('hud-dom').hidden=true; this.showScreen('title'); Audio_.stopMusic(); }
  endGame(reason){
    this.state='gameover';
    this.gameOverReason=reason;
    document.getElementById('hud-dom').hidden=true;
    Audio_.stopMusic(); Audio_.heliStop();
    document.getElementById('gameover-title').textContent = reason==='destroyed' ? 'Car Destroyed' : "Time's Up";
    document.getElementById('gameover-score').textContent = String(Math.floor(this.score)).padStart(6,'0');
    const qualifies = this.highscores.length<10 || this.score>this.highscores[this.highscores.length-1].score;
    document.getElementById('name-entry').hidden = !qualifies;
    this.renderHighscoreTable(-1);
    this.showScreen('gameover');
  }
  loadHighscores(){
    try{ return JSON.parse(localStorage.getItem('neonPursuitHighscores')||'[]'); }catch(e){ return []; }
  }
  saveHighscores(){ try{ localStorage.setItem('neonPursuitHighscores', JSON.stringify(this.highscores)); }catch(e){} }
  submitHighscore(){
    const name=(document.getElementById('hs-name').value||'AAA').slice(0,3).toUpperCase();
    this.highscores.push({ name, score:Math.floor(this.score) });
    this.highscores.sort((a,b)=>b.score-a.score);
    this.highscores = this.highscores.slice(0,10);
    this.saveHighscores();
    document.getElementById('name-entry').hidden=true;
    this.renderHighscoreTable(this.highscores.findIndex(h=>h.name===name && h.score===Math.floor(this.score)));
  }
  renderHighscoreTable(highlightIdx){
    const table=document.getElementById('hs-table');
    table.innerHTML = this.highscores.map((h,i)=>`<tr class="${i===highlightIdx?'me':''}"><td>${i+1}.</td><td>${h.name}</td><td style="text-align:right;">${String(h.score).padStart(6,'0')}</td></tr>`).join('') || '<tr><td colspan=3 style="text-align:center;color:var(--ink-dim);">No scores yet</td></tr>';
  }

  // -------------------- UPDATE: PLAYER PHYSICS --------------------
  updatePlayer(dt){
    const p=this.player;
    Input.update();
    const speedFrac = clamp(p.speed / CFG.MAX_SPEED, -1, 1);

    // steering
    const steerTarget = Input.steer*CFG.MAX_STEER*(1-0.4*Math.abs(speedFrac)*0.5);
    p.steerAngle = lerp(p.steerAngle, steerTarget, 1-Math.pow(0.001,dt));

    // throttle / brake / reverse
    let accel=0;
    if(Input.throttle>0) accel = CFG.ACCEL*Input.throttle;
    if(Input.brake>0){
      if(p.speed>0.5) accel -= CFG.BRAKE*Input.brake;
      else accel -= CFG.REVERSE_ACCEL*Input.brake;
    }
    p.braking = Input.brake>0 && p.speed>0.5;

    // nitro
    if(Input.nitro && this.nitroAmount>0.02 && !p.braking){
      this.nitroActive=true;
    }
    if(!Input.nitro || this.nitroAmount<=0) this.nitroActive=false;
    const maxSpeed = this.nitroActive? CFG.NITRO_MAX_SPEED : CFG.MAX_SPEED;
    if(this.nitroActive){ this.nitroAmount = Math.max(0,this.nitroAmount - dt/CFG.NITRO_DURATION); accel += 30; }
    else { this.nitroAmount = Math.min(1, this.nitroAmount + dt/CFG.NITRO_REGEN_TIME); }

    p.speed += accel*dt;
    p.speed = clamp(p.speed, -CFG.MAX_SPEED*0.4, maxSpeed);
    const drag = p.offroad? CFG.OFFROAD_DRAG : CFG.DRAG;
    p.speed *= Math.pow(drag, dt*60);
    if(Math.abs(p.speed)<0.05 && accel===0) p.speed=0;

    // heading integration from steering (bicycle-ish model)
    const steerEff = p.steerAngle * clamp(Math.abs(p.speed)/8,0,1) * Math.sign(p.speed||1);
    p.heading += steerEff*dt*1.6;

    // lateral slip / drift
    const desiredLateral = Math.sin(p.heading)*p.speed;
    const forwardSpeed = Math.cos(p.heading)*p.speed;
    const slip = Math.abs(Input.steer)>0.5 && Math.abs(p.speed)>14;
    p.drifting = slip && Math.abs(p.steerAngle)>0.25;
    const gripFactor = p.drifting? CFG.DRIFT_GRIP : CFG.GRIP;
    p.lateralVel = lerp(p.lateralVel, desiredLateral, clamp(gripFactor*dt,0,1));

    if(p.drifting){ p.driftTime+=dt; } else { if(p.driftTime>0.4) this.addDriftScore(p.driftTime); p.driftTime=0; }

    p.x += p.lateralVel*dt;
    p.z += forwardSpeed*dt;
    this.distance = Math.max(this.distance, p.z);

    // road following
    const center = this.getRoadCenter(p.z);
    const halfW = CFG.ROAD_WIDTH/2;
    const relX = p.x - center.x;
    p.offroad = Math.abs(relX) > halfW;
    if(Math.abs(relX) > halfW+6){
      // clamp hard at far edge
      p.x = center.x + Math.sign(relX)*(halfW+6);
    }
    p.y = lerp(p.y, center.y, clamp(dt*6,0,1));

    // wheel visuals
    p.wheelSpin += p.speed*dt*0.9;
    const mesh=p.mesh;
    mesh.position.set(p.x, p.y, p.z);
    mesh.rotation.y = -p.heading;
    mesh.rotation.z = lerp(mesh.rotation.z, -p.lateralVel*0.01, 0.1);
    for(const w of mesh.userData.wheels) w.rotation.x = p.wheelSpin;
    for(const w of mesh.userData.frontWheels) w.rotation.y = p.steerAngle*1.3;
    const tilt = clamp(-accel*0.01,-0.08,0.08);
    mesh.rotation.x = lerp(mesh.rotation.x, tilt, 0.1);

    // taillights brighten on brake
    mesh.userData.taillightMat.emissiveIntensity = p.braking? 3.2 : 1.2;

    // headlights active at night/dusk
    const sb = stageBlend(this.distance);
    const nightish = (sb.a==='night'||sb.a==='dusk') ;
    this.headlightL.intensity = nightish? 2.2:0; this.headlightR.intensity = nightish? 2.2:0;

    // drift smoke
    if(p.drifting && Math.random()<0.8){
      const side = Math.sign(p.lateralVel-desiredLateral)||1;
      for(let i=0;i<2;i++){
        this.smokeFX.spawn(
          new THREE.Vector3(p.x+srange(-1,1)*0.9, 0.3, p.z-1.3+srange(-0.3,0.3)),
          new THREE.Vector3(srange(-0.5,0.5),0.6,-p.speed*0.08),
          1.0+Math.random()*0.6, 0.8, { colorStart:new THREE.Color(0xcccccc), colorEnd:new THREE.Color(0x555555), growth:1.4, gravity:-0.2 }
        );
      }
    }
    // offroad sand kickup
    if(p.offroad && Math.abs(p.speed)>5 && Math.random()<0.6){
      this.sandFX.spawn(new THREE.Vector3(p.x,0.1,p.z-1.5), new THREE.Vector3(srange(-1,1),1.5,-p.speed*0.1), 0.6, 0.5, { colorStart:new THREE.Color(0xd8c08a), colorEnd:new THREE.Color(0xd8c08a), growth:0.6, gravity:1.5 });
    }
    // engine sound
    Audio_.engineUpdate(Math.max(Input.throttle,Math.abs(accel)>0?0.3:0), clamp(Math.abs(p.speed)/maxSpeed,0,1), dt, this.clock.elapsedTime);
    if(p.drifting && Math.random()<0.15) Audio_.sfxScreech();

    // screen damage visuals: smoke/fire if low health
    this.updateDamageFX(dt);

    // camera
    this.updateCamera(dt, speedFrac);

    // weapons
    this.updateWeaponsInput(dt);

    // checkpoints / timer
    this.time -= dt;
    if(this.distance >= this.nextCheckpoint){
      this.nextCheckpoint += CFG.CHECKPOINT_SPACING;
      this.time += CFG.CHECKPOINT_TIME;
      Audio_.sfxChime();
      this.score += 250;
    }
    if(this.time<=0){ this.endGame('time'); }
    if(this.time<6 && Math.floor(this.time*2)!==Math.floor((this.time+dt)*2)) Audio_.sfxBeepWarn();

    // distance score
    this.score += Math.abs(forwardSpeed)*dt*0.6;

    // combo decay
    if(this.comboTimer>0){ this.comboTimer-=dt; if(this.comboTimer<=0) this.combo=1; }

    // fork UI prompt
    const zone = this.isForkZoneAt(p.z);
    this.el.forkPrompt.hidden = !(zone && zone.local < CFG.FORK_DECIDE_AT);
  }
  addDriftScore(driftTime){
    const pts = Math.floor(driftTime*120*this.combo);
    this.score += pts;
    this.combo = Math.min(8, this.combo+1);
    this.comboTimer = 3;
  }
  updateCamera(dt, speedFrac){
    const p=this.player;
    const camDist = 7.2, camHeight = 2.8;
    const targetPos = new THREE.Vector3(
      p.x - Math.sin(p.heading)*camDist,
      p.y + camHeight,
      p.z - Math.cos(p.heading)*camDist
    );
    this.camera.position.lerp(targetPos, 1-Math.pow(0.0001,dt));
    const lookAt = new THREE.Vector3(p.x+Math.sin(p.heading)*4, p.y+1.2, p.z+Math.cos(p.heading)*4);
    this._camLook = this._camLook? this._camLook.lerp(lookAt,1-Math.pow(0.0005,dt)) : lookAt.clone();
    this.camera.lookAt(this._camLook);
    const targetFov = 62 + (this.nitroActive?14:0) + Math.abs(speedFrac)*6;
    this.camera.fov = lerp(this.camera.fov, targetFov, 1-Math.pow(0.001,dt));
    this.camera.updateProjectionMatrix();
    // shake
    let shake = Math.max(0, Math.abs(p.speed)/CFG.MAX_SPEED - 0.65)*0.12;
    if(this.cameraShakeImpulse>0){ shake += this.cameraShakeImpulse; this.cameraShakeImpulse*=0.9; }
    if(shake>0.001){
      this.camera.position.x += srange(-1,1)*shake;
      this.camera.position.y += srange(-1,1)*shake*0.6;
    }
  }
  updateDamageFX(dt){
    const hpFrac = this.health/CFG.PLAYER_MAX_HEALTH;
    if(hpFrac<0.5 && Math.random()<0.5){
      const p=this.player;
      this.smokeFX.spawn(new THREE.Vector3(p.x+srange(-0.5,0.5),0.9,p.z+1.6), new THREE.Vector3(0,1.2,0), 0.9,0.6,
        { colorStart:new THREE.Color(hpFrac<0.25?0x442222:0x888888), colorEnd:new THREE.Color(0x333333), growth:1.0, gravity:-0.3 });
    }
    if(hpFrac<0.25 && Math.random()<0.4){
      const p=this.player;
      this.explosionFX.spawn(new THREE.Vector3(p.x+srange(-0.4,0.4),0.7,p.z+1.5), new THREE.Vector3(0,0.8,0), 0.35,0.4,
        { colorStart:new THREE.Color(0xff6a2a), colorEnd:new THREE.Color(0x441100), growth:0.3 });
    }
  }

  // -------------------- WEAPONS --------------------
  updateWeaponsInput(dt){
    this.gunCooldown=Math.max(0,this.gunCooldown-dt);
    this.missileCooldown=Math.max(0,this.missileCooldown-dt);
    this.oilCooldown=Math.max(0,this.oilCooldown-dt);
    this.smokeCooldown=Math.max(0,this.smokeCooldown-dt);
    if(this.shieldTimer>0){ this.shieldTimer-=dt; if(this.shieldTimer<=0) this.shieldActive=false; }

    if(Input.fire && this.gunCooldown<=0){
      this.gunCooldown=CFG.GUN_COOLDOWN;
      this.fireBullet();
      if(this.ammoMissiles>0 && this.missileCooldown<=0 && Math.random()<0.15){ /* missiles auto-used via separate key could be added; keep gun primary */ }
    }
    if(Input.oilEdge && this.oilCooldown<=0){ this.oilCooldown=1.2; this.dropOilSlick(); }
    if(Input.smokeEdge && this.smokeCooldown<=0){ this.smokeCooldown=2.0; this.dropSmokeScreen(); }
    // auto-fire missile with fire key when ammo available and gun just fired twice (simple secondary fire via holding fire + having ammo uses occasional missile)
    if(Input.fire && this.ammoMissiles>0 && this.missileCooldown<=0){
      this.missileCooldown=CFG.MISSILE_COOLDOWN*2.4;
      this.fireMissile();
    }
  }
  fireBullet(){
    const p=this.player;
    Audio_.sfxGunshot();
    const dir=new THREE.Vector3(Math.sin(p.heading),0,Math.cos(p.heading));
    for(const side of [-0.55,0.55]){
      const geo=new THREE.SphereGeometry(0.08,6,6);
      const mat=new THREE.MeshBasicMaterial({color:0xfff2a0});
      const m=new THREE.Mesh(geo,mat);
      const offset=new THREE.Vector3(Math.cos(p.heading)*side,0.55,-Math.sin(p.heading)*side);
      m.position.set(p.x+offset.x, p.y+offset.y, p.z+offset.z+2.1);
      this.worldGroup.add(m);
      this.projectiles.push({ mesh:m, vel:dir.clone().multiplyScalar(90).add(new THREE.Vector3(0,0,p.speed)), life:1.2, dmg:CFG.BULLET_DAMAGE });
      this.muzzleFX.spawn(m.position.clone(), new THREE.Vector3(0,0,0), 0.08, 0.4, { colorStart:new THREE.Color(0xfff2a0), colorEnd:new THREE.Color(0xff8a2a) });
    }
  }
  fireMissile(){
    const p=this.player;
    this.ammoMissiles--; Audio_.sfxMissile();
    const geo=new THREE.CylinderGeometry(0.1,0.1,0.6,8); geo.rotateX(Math.PI/2);
    const mat=new THREE.MeshStandardMaterial({color:0xdddddd, emissive:0xff4422, emissiveIntensity:0.6});
    const m=new THREE.Mesh(geo,mat);
    m.position.set(p.x,p.y+0.6,p.z+2.3);
    this.worldGroup.add(m);
    this.missiles.push({ mesh:m, target:null, z:p.z, x:p.x, speed:46, life:3 });
  }
  dropOilSlick(){
    const p=this.player;
    const geo=new THREE.CircleGeometry(1.6,16); geo.rotateX(-Math.PI/2);
    const mat=new THREE.MeshStandardMaterial({ color:0x0a0a0a, roughness:0.1, metalness:0.8, transparent:true, opacity:0.85 });
    const m=new THREE.Mesh(geo,mat); m.position.set(p.x,p.y+0.03,p.z-2.5);
    this.worldGroup.add(m);
    this.oilSlicks.push({ mesh:m, z:m.position.z, x:p.x, life:14 });
  }
  dropSmokeScreen(){
    const p=this.player;
    this.smokeClouds.push({ x:p.x, z:p.z-2, life:5, radius:4 });
    for(let i=0;i<14;i++){
      this.smokeFX.spawn(new THREE.Vector3(p.x+srange(-2,2),0.6+srange(0,1),p.z-2+srange(-2,2)), new THREE.Vector3(srange(-0.3,0.3),0.3,0), 3+Math.random(), 1.6,
        { colorStart:new THREE.Color(0xaaaaaa), colorEnd:new THREE.Color(0x444444), growth:2.0, fadeOut:true });
    }
  }

  // -------------------- ENTITY SPAWNING --------------------
  maybeSpawnEntities(dt){
    const aheadZ = this.player.z + 160;
    const diffScale = 1 + clamp(this.distance/4000,0,1.2);
    this._spawnAccEnemy = (this._spawnAccEnemy||0) + dt*CFG.ENEMY_BASE_DENSITY*diffScale*20;
    this._spawnAccCiv = (this._spawnAccCiv||0) + dt*CFG.CIVILIAN_BASE_DENSITY*20;
    if(this._spawnAccEnemy>1 && this.enemies.length<10){ this._spawnAccEnemy=0; this.spawnEnemy(aheadZ); }
    if(this._spawnAccCiv>1 && this.civilians.length<8){ this._spawnAccCiv=0; this.spawnCivilian(aheadZ); }
    if(this.distance+140 > this.nextPickup && this.pickups.length<2){
      this.nextPickup += CFG.PICKUP_SPACING;
      this.spawnPickup(this.player.z+150);
    }
  }
  spawnEnemy(z){
    const types=['ram','ram','bike','truck'];
    if(this.distance>1500) types.push('heli');
    const type=pick(types);
    const center=this.getRoadCenter(z);
    const laneX = center.x + srange(-1,1)*CFG.ROAD_WIDTH*0.3;
    let mesh, data;
    if(type==='ram'){
      mesh=buildCarBody(pick([0x2244aa,0x333344,0x555522]), 0x111318);
      data={ type, hp:50, speed:this.player.speed*0.9+srange(5,15) };
    } else if(type==='bike'){
      mesh=buildMotorbike(); data={ type, hp:25, speed:this.player.speed+srange(5,12), shootTimer:srange(0.5,1.5) };
    } else if(type==='truck'){
      mesh=buildTruck(); data={ type, hp:90, speed:this.player.speed*0.7+srange(0,6), dropTimer:srange(1,2) };
    } else {
      mesh=buildHelicopter(); data={ type, hp:70, speed:this.player.speed, strafeTimer:srange(1,2), hoverPhase:Math.random()*10 };
      Audio_.heliStart();
    }
    mesh.castShadow=true;
    this.worldGroup.add(mesh);
    const e={ mesh, x:laneX, z, y:0, heading:0, data, hp:data.hp, maxHp:data.hp, alive:true, mesh_t:0 };
    this.enemies.push(e);
  }
  spawnCivilian(z){
    const center=this.getRoadCenter(z);
    const lane = pick([-1,1])*CFG.ROAD_WIDTH*0.28;
    const mesh=buildCarBody(pick([0xdddddd,0xcc8822,0x228844,0x884422]), 0x101014);
    mesh.castShadow=true; this.worldGroup.add(mesh);
    this.civilians.push({ mesh, x:center.x+lane, z, speed:this.player.speed*0.75+srange(-4,6), laneOffset:lane });
  }
  spawnPickup(z){
    const center=this.getRoadCenter(z);
    const kind = Math.random()>0.5?'missile':'shield';
    const mesh = buildTruck();
    mesh.scale.set(0.9,0.9,0.9);
    mesh.children.forEach(c=>{ if(c.material && c.material.color) {} });
    const glowMat = new THREE.MeshStandardMaterial({ color: kind==='missile'?0xff6a2a:0x2de2ff, emissive: kind==='missile'?0xff6a2a:0x2de2ff, emissiveIntensity:1.4, metalness:0.4, roughness:0.3 });
    mesh.children[0].material = glowMat;
    this.worldGroup.add(mesh);
    this.pickups.push({ mesh, x:center.x, z, kind, speed:this.player.speed*0.6+6 });
  }

  // -------------------- UPDATE: AI / COMBAT --------------------
  updateEntities(dt){
    this.maybeSpawnEntities(dt);
    const p=this.player;
    const removeDist=60, despawnBehind=40;

    // enemies
    for(let i=this.enemies.length-1;i>=0;i--){
      const e=this.enemies[i];
      if(!e.alive) continue;
      const center=this.getRoadCenter(e.z);
      if(e.data.type==='ram'){
        const dx = p.x - e.x;
        e.x += clamp(dx,-1,1)*dt*4.2;
        e.z += e.data.speed*dt;
        e.heading = lerp(e.heading, Math.atan2(dx*0.3,1)*0.3, dt*2);
      } else if(e.data.type==='bike'){
        e.x = center.x + Math.sin(this.clock.elapsedTime*1.5+e.z*0.01)*3;
        e.z += e.data.speed*dt;
        e.data.shootTimer -= dt;
        if(e.data.shootTimer<=0 && Math.abs(e.z-p.z)<60){
          e.data.shootTimer = srange(0.9,1.6);
          this.enemyShoot(e);
        }
      } else if(e.data.type==='truck'){
        e.x = lerp(e.x, center.x, dt*0.5);
        e.z += e.data.speed*dt;
        e.data.dropTimer -= dt;
        if(e.data.dropTimer<=0 && e.z>p.z+6){
          e.data.dropTimer=srange(1.4,2.4);
          this.spawnBarrel(e.x,e.z-3);
        }
      } else if(e.data.type==='heli'){
        e.data.strafeTimer -= dt;
        e.x = center.x + Math.sin(this.clock.elapsedTime*0.6)*8;
        e.z = p.z + 18 + Math.sin(this.clock.elapsedTime*0.4)*6;
        e.y = 6+Math.sin(this.clock.elapsedTime*1.2)*0.6;
        if(e.mesh.userData.rotor) e.mesh.userData.rotor.rotation.y += dt*40;
        if(e.mesh.userData.blinkLight) e.mesh.userData.blinkLight.visible = Math.sin(this.clock.elapsedTime*8)>0;
        Audio_.heliSet(clamp(1-Math.abs(e.z-p.z)/60,0,1)*0.3);
        if(e.data.strafeTimer<=0){ e.data.strafeTimer=srange(1.2,2.0); this.enemyShoot(e); }
      }
      e.mesh.position.set(e.x, e.y, e.z);
      e.mesh.rotation.y = -e.heading + (e.z<p.z?Math.PI:0);
      if(e.mesh.userData.wheels) for(const w of e.mesh.userData.wheels) w.rotation.x += (e.data.speed||10)*dt*0.9;

      // collision with player (ram damage)
      const dz=e.z-p.z, dx=e.x-p.x;
      if(Math.abs(dz)<2.6 && Math.abs(dx)<1.8 && e.data.type!=='heli'){
        this.damagePlayer(e.data.type==='truck'?14:8, dt);
        this.pushApart(e,p,dt);
        this.spawnSparks(p.x+dx*0.5,p.y+0.6,p.z+dz*0.5);
      }
      // collision with bullets handled in projectile loop

      if(e.z < p.z-despawnBehind || e.z>p.z+400){ this.worldGroup.remove(e.mesh); this.enemies.splice(i,1); if(e.data.type==='heli') Audio_.heliStop(); }
    }
    // civilians
    for(let i=this.civilians.length-1;i>=0;i--){
      const c=this.civilians[i];
      const center=this.getRoadCenter(c.z);
      c.x = lerp(c.x, center.x+c.laneOffset, dt*0.5);
      c.z += c.speed*dt;
      c.mesh.position.set(c.x,0,c.z);
      c.mesh.rotation.y = Math.PI;
      if(c.mesh.userData.wheels) for(const w of c.mesh.userData.wheels) w.rotation.x += c.speed*dt*0.9;
      const dz=c.z-p.z, dx=c.x-p.x;
      if(Math.abs(dz)<2.4 && Math.abs(dx)<1.7){
        this.score = Math.max(0,this.score+CFG.CIVILIAN_HIT_PENALTY_SCORE);
        this.time += CFG.CIVILIAN_HIT_PENALTY_TIME;
        this.damagePlayer(6,dt);
        this.pushApart(c,p,dt);
        this.flashCrash();
        Audio_.sfxCrash();
      }
      if(c.z < p.z-despawnBehind || c.z>p.z+300){ this.worldGroup.remove(c.mesh); this.civilians.splice(i,1); }
    }
    // projectiles (player bullets)
    for(let i=this.projectiles.length-1;i>=0;i--){
      const b=this.projectiles[i];
      b.mesh.position.addScaledVector(b.vel,dt);
      b.life-=dt;
      let hit=false;
      for(const e of this.enemies){
        if(!e.alive) continue;
        if(e.mesh.position.distanceTo(b.mesh.position)<1.6){ this.hitEnemy(e,b.dmg); hit=true; break; }
      }
      if(hit || b.life<=0){ this.worldGroup.remove(b.mesh); this.projectiles.splice(i,1); }
    }
    // missiles (homing-ish toward nearest enemy ahead)
    for(let i=this.missiles.length-1;i>=0;i--){
      const m=this.missiles[i];
      let target=null, best=1e9;
      for(const e of this.enemies){ if(!e.alive) continue; const d=e.mesh.position.distanceTo(m.mesh.position); if(d<best && e.z>m.mesh.position.z-5){ best=d; target=e; } }
      const dir=new THREE.Vector3(0,0,1);
      if(target){ dir.copy(target.mesh.position).sub(m.mesh.position).normalize(); }
      m.mesh.position.addScaledVector(dir, m.speed*dt);
      m.mesh.lookAt(m.mesh.position.clone().add(dir));
      this.smokeFX.spawn(m.mesh.position.clone(), new THREE.Vector3(0,0.2,0), 0.4,0.3,{colorStart:new THREE.Color(0xcccccc),colorEnd:new THREE.Color(0x666666)});
      m.life-=dt;
      let hit=false;
      if(target && target.mesh.position.distanceTo(m.mesh.position)<2.2){ this.hitEnemy(target,CFG.MISSILE_DAMAGE); this.bigExplosion(m.mesh.position); hit=true; }
      if(hit || m.life<=0){ if(!hit) this.bigExplosion(m.mesh.position); this.worldGroup.remove(m.mesh); this.missiles.splice(i,1); }
    }
    // oil slicks
    for(let i=this.oilSlicks.length-1;i>=0;i--){
      const o=this.oilSlicks[i]; o.life-=dt;
      const dz=o.z-p.z, dx=o.x-p.x;
      if(Math.abs(dz)<2 && Math.abs(dx)<2 && !o.hitPlayer){
        o.hitPlayer=true; this.player.lateralVel += srange(-8,8); Audio_.sfxScreech();
      }
      for(const e of this.enemies){ if(e.alive && Math.abs(e.z-o.z)<2 && Math.abs(e.x-o.x)<2 && !e._sliped){ e._sliped=true; e.x+=srange(-4,4); } }
      if(o.life<=0 || o.z<p.z-despawnBehind){ this.worldGroup.remove(o.mesh); this.oilSlicks.splice(i,1); }
    }
    // smoke screens (gameplay effect: block enemy shooting if close - simplified as just visuals + slight civilian/enemy confusion already covered by particles)
    for(let i=this.smokeClouds.length-1;i>=0;i--){ this.smokeClouds[i].life-=dt; if(this.smokeClouds[i].life<=0) this.smokeClouds.splice(i,1); }
    // barrels
    if(this.barrels){
      for(let i=this.barrels.length-1;i>=0;i--){
        const b=this.barrels[i];
        b.z -= (b.speed||0)*dt;
        b.mesh.position.set(b.x,0.4,b.z);
        b.mesh.rotation.x += dt*4;
        const dz=b.z-p.z, dx=b.x-p.x;
        if(Math.abs(dz)<1.8 && Math.abs(dx)<1.6){ this.damagePlayer(12,dt); this.bigExplosion(b.mesh.position); this.worldGroup.remove(b.mesh); this.barrels.splice(i,1); continue; }
        if(b.z < p.z-despawnBehind){ this.worldGroup.remove(b.mesh); this.barrels.splice(i,1); }
      }
    }
    // pickups
    for(let i=this.pickups.length-1;i>=0;i--){
      const pk=this.pickups[i];
      pk.mesh.position.set(pk.x,0,pk.z);
      pk.mesh.rotation.y += dt*1.5;
      const dz=pk.z-p.z, dx=pk.x-p.x;
      if(Math.abs(dz)<2.4 && Math.abs(dx)<2.0){
        Audio_.sfxPickup();
        if(pk.kind==='missile') this.ammoMissiles = Math.min(9,this.ammoMissiles+3);
        else { this.shieldActive=true; this.shieldTimer=8; }
        this.worldGroup.remove(pk.mesh); this.pickups.splice(i,1); continue;
      }
      if(pk.z < p.z-despawnBehind){ this.worldGroup.remove(pk.mesh); this.pickups.splice(i,1); }
    }

    this.smokeFX.update(dt); this.sparkFX.update(dt); this.explosionFX.update(dt); this.muzzleFX.update(dt); this.sandFX.update(dt);
  }
  enemyShoot(e){
    const p=this.player;
    const dir=new THREE.Vector3(p.x-e.x,0,p.z-e.z).normalize();
    const geo=new THREE.SphereGeometry(0.1,6,6); const mat=new THREE.MeshBasicMaterial({color:0xff5555});
    const m=new THREE.Mesh(geo,mat); m.position.set(e.x,0.8,e.z);
    this.worldGroup.add(m);
    if(!this.enemyBullets) this.enemyBullets=[];
    this.enemyBullets.push({ mesh:m, vel:dir.multiplyScalar(50), life:2 });
    Audio_.sfxGunshot();
  }
  updateEnemyBullets(dt){
    if(!this.enemyBullets) return;
    const p=this.player;
    for(let i=this.enemyBullets.length-1;i>=0;i--){
      const b=this.enemyBullets[i];
      b.mesh.position.addScaledVector(b.vel,dt); b.life-=dt;
      if(b.mesh.position.distanceTo(p.mesh.position)<1.3){
        this.damagePlayer(10,dt); this.worldGroup.remove(b.mesh); this.enemyBullets.splice(i,1); continue;
      }
      if(b.life<=0){ this.worldGroup.remove(b.mesh); this.enemyBullets.splice(i,1); }
    }
  }
  spawnBarrel(x,z){
    if(!this.barrels) this.barrels=[];
    const mesh=new THREE.Mesh(new THREE.CylinderGeometry(0.5,0.5,0.8,10), new THREE.MeshStandardMaterial({color:0x883322,roughness:0.7}));
    mesh.position.set(x,0.4,z); this.worldGroup.add(mesh);
    this.barrels.push({ mesh, x, z, speed:this.player.speed*0.3 });
  }
  hitEnemy(e,dmg){
    e.hp -= dmg;
    this.spawnSparks(e.mesh.position.x,e.mesh.position.y+0.6,e.mesh.position.z);
    if(e.hp<=0 && e.alive){
      e.alive=false;
      this.score += 600*this.combo;
      this.bigExplosion(e.mesh.position);
      Audio_.sfxExplosion(e.data.type==='truck');
      if(e.data.type==='heli') Audio_.heliStop();
      this.worldGroup.remove(e.mesh);
      const idx=this.enemies.indexOf(e); if(idx>=0) this.enemies.splice(idx,1);
    }
  }
  pushApart(a,p,dt){
    const dx = p.x-a.x; const push = clamp(1.2-Math.abs(dx),0,1.2);
    p.lateralVel += Math.sign(dx||1)*push*18*dt*10;
  }
  spawnSparks(x,y,z){
    for(let i=0;i<6;i++){
      this.sparkFX.spawn(new THREE.Vector3(x,y,z), new THREE.Vector3(srange(-3,3),srange(1,4),srange(-3,3)), 0.4+Math.random()*0.3, 0.15,
        { colorStart:new THREE.Color(0xffee88), colorEnd:new THREE.Color(0xff5500), gravity:6 });
    }
  }
  bigExplosion(pos){
    for(let i=0;i<18;i++){
      this.explosionFX.spawn(pos.clone(), new THREE.Vector3(srange(-4,4),srange(1,6),srange(-4,4)), 0.5+Math.random()*0.5, 0.6+Math.random()*0.6,
        { colorStart:new THREE.Color(0xffd27a), colorEnd:new THREE.Color(0x331100), growth:1.6, gravity:3 });
    }
  }
  flashCrash(){
    this.el.crashFlash.style.transition='none';
    this.el.crashFlash.style.opacity='0.55';
    requestAnimationFrame(()=>{ this.el.crashFlash.style.transition='opacity 0.4s'; this.el.crashFlash.style.opacity='0'; });
    this.cameraShakeImpulse = 0.3;
  }
  damagePlayer(amount){
    if(this.shieldActive) return;
    this.health -= amount;
    this.flashCrash();
    Audio_.sfxCrash();
    if(this.health<=0){ this.health=0; this.bigExplosion(this.player.mesh.position); Audio_.sfxExplosion(true); this.endGame('destroyed'); }
  }

  // -------------------- HUD DRAWING --------------------
  updateHUD(){
    const sb = stageBlend(this.distance);
    this.el.stageName.textContent = sb.name;
    const t = Math.max(0,this.time);
    this.el.timer.textContent = t.toFixed(1);
    this.el.timer.classList.toggle('low', t<10);
    this.el.scoreVal.textContent = String(Math.floor(this.score)).padStart(6,'0');
    this.el.comboRow.textContent = this.combo>1 ? `COMBO x${this.combo}` : '';
    const hpPct = Math.round(100*this.health/CFG.PLAYER_MAX_HEALTH);
    this.el.healthFill.style.width = hpPct+'%';
    this.el.healthPct.textContent = hpPct+'%';
    this.el.healthFill.style.background = hpPct<30? 'linear-gradient(90deg,#ff3b5c,#ff8a8a)' : hpPct<60? 'linear-gradient(90deg,#ffd23f,#ffe9a0)' : 'linear-gradient(90deg,#3dffa0,#9dffb8)';
    document.getElementById('nitro-bar-fill').style.width = Math.round(this.nitroAmount*100)+'%';
    this.el.chipMissile.textContent = `MSL x${this.ammoMissiles}`;
    this.el.chipMissile.classList.toggle('off', this.ammoMissiles<=0);
    this.el.chipShield.classList.toggle('off', !this.shieldActive);
    this.el.chipShield.classList.toggle('active', this.shieldActive);
    this.drawSpeedo();
    this.drawMinimap();
  }
  drawSpeedo(){
    const ctx=this.speedoCtx, w=this.speedoCanvas.width, h=this.speedoCanvas.height;
    ctx.clearRect(0,0,w,h);
    const cx=w/2, cy=h/2, r=w/2-10;
    ctx.save(); ctx.translate(cx,cy);
    ctx.strokeStyle='rgba(139,47,255,0.5)'; ctx.lineWidth=3;
    ctx.beginPath(); ctx.arc(0,0,r,Math.PI*0.72,Math.PI*2.28); ctx.stroke();
    const speedKmh = Math.abs(this.player.speed)*3.0;
    const maxShow=220;
    for(let s=0;s<=maxShow;s+=20){
      const a = Math.PI*0.72 + (s/maxShow)*Math.PI*1.56;
      const inner=r-10, outer=r;
      ctx.strokeStyle = s>160?'#ff3b5c':'#2de2ff'; ctx.lineWidth=2;
      ctx.beginPath(); ctx.moveTo(Math.cos(a)*inner,Math.sin(a)*inner); ctx.lineTo(Math.cos(a)*outer,Math.sin(a)*outer); ctx.stroke();
    }
    const frac=clamp(speedKmh/maxShow,0,1);
    const needleA = Math.PI*0.72 + frac*Math.PI*1.56;
    ctx.strokeStyle='#ff2e9a'; ctx.lineWidth=3; ctx.shadowColor='#ff2e9a'; ctx.shadowBlur=8;
    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(Math.cos(needleA)*(r-16), Math.sin(needleA)*(r-16)); ctx.stroke();
    ctx.shadowBlur=0;
    ctx.fillStyle='#2de2ff'; ctx.beginPath(); ctx.arc(0,0,5,0,Math.PI*2); ctx.fill();
    ctx.restore();
    ctx.fillStyle='#f2e9ff'; ctx.font='700 20px Orbitron'; ctx.textAlign='center';
    ctx.fillText(Math.round(speedKmh), cx, cy+r*0.55);
    ctx.font='600 10px Rajdhani'; ctx.fillStyle='#a898c8'; ctx.fillText('KM/H', cx, cy+r*0.55+16);
    if(this.nitroActive){ ctx.fillStyle='#ffd23f'; ctx.font='700 11px Orbitron'; ctx.fillText('NOS', cx, cy-r*0.4); }
  }
  drawMinimap(){
    const ctx=this.minimapCtx, w=this.minimapCanvas.width, h=this.minimapCanvas.height;
    ctx.clearRect(0,0,w,h);
    ctx.save();
    ctx.beginPath(); ctx.arc(w/2,h/2,w/2-2,0,Math.PI*2); ctx.clip();
    ctx.fillStyle='rgba(10,6,20,0.7)'; ctx.fillRect(0,0,w,h);
    const range=160, samples=28;
    ctx.strokeStyle='#2de2ff'; ctx.lineWidth=3; ctx.beginPath();
    const baseX=this.getRoadCenter(this.player.z).x;
    for(let i=0;i<=samples;i++){
      const z=this.player.z + (i/samples)*range;
      const c=this.getRoadCenter(z);
      const mx = w/2 + (c.x-baseX)*2.2;
      const my = h - (i/samples)*h;
      if(i===0) ctx.moveTo(mx,my); else ctx.lineTo(mx,my);
    }
    ctx.stroke();
    // enemies/civilians as dots
    for(const e of this.enemies){
      const mx=w/2+(e.x-baseX)*2.2, my=h-((e.z-this.player.z)/range)*h;
      if(my<0||my>h) continue;
      ctx.fillStyle='#ff3b5c'; ctx.beginPath(); ctx.arc(mx,my,3,0,Math.PI*2); ctx.fill();
    }
    for(const c of this.civilians){
      const mx=w/2+(c.x-baseX)*2.2, my=h-((c.z-this.player.z)/range)*h;
      if(my<0||my>h) continue;
      ctx.fillStyle='#8899aa'; ctx.beginPath(); ctx.arc(mx,my,2.4,0,Math.PI*2); ctx.fill();
    }
    ctx.fillStyle='#ffd23f'; ctx.beginPath(); ctx.arc(w/2,h-6,4,0,Math.PI*2); ctx.fill();
    ctx.restore();
    ctx.strokeStyle='rgba(139,47,255,0.6)'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(w/2,h/2,w/2-2,0,Math.PI*2); ctx.stroke();
  }

  // -------------------- SKY / LIGHTING UPDATE --------------------
  updateSky(dt){
    const sb = stageBlend(this.distance);
    const pa = SKY_PALETTES[sb.a], pb = SKY_PALETTES[sb.b];
    const t = sb.t;
    const topC = new THREE.Color(pa.top).lerp(new THREE.Color(pb.top), t);
    const botC = new THREE.Color(pa.bottom).lerp(new THREE.Color(pb.bottom), t);
    const sunC = new THREE.Color(pa.sun).lerp(new THREE.Color(pb.sun), t);
    const fogC = new THREE.Color(pa.fog).lerp(new THREE.Color(pb.fog), t);
    const hemiSky = new THREE.Color(pa.hemiSky).lerp(new THREE.Color(pb.hemiSky), t);
    const hemiGround = new THREE.Color(pa.hemiGround).lerp(new THREE.Color(pb.hemiGround), t);
    const dirColor = new THREE.Color(pa.dirColor).lerp(new THREE.Color(pb.dirColor), t);
    const dirInt = lerp(pa.dirInt,pb.dirInt,t);
    const ambient = lerp(pa.ambient,pb.ambient,t);
    const stars = lerp(pa.stars,pb.stars,t);
    const sunY = lerp(pa.sunY,pb.sunY,t);

    this.skyMat.uniforms.topColor.value.copy(topC);
    this.skyMat.uniforms.bottomColor.value.copy(botC);
    this.skyMat.uniforms.sunColor.value.copy(sunC);
    this.skyMat.uniforms.sunY.value = sunY;
    this.skyMat.uniforms.sunX.value = 0.25;
    this.skyMat.uniforms.starAmount.value = stars;
    this.skyMat.uniforms.time.value += dt;

    this.scene.fog.color.copy(fogC);
    this.hemi.color.copy(hemiSky); this.hemi.groundColor.copy(hemiGround); this.hemi.intensity=ambient+0.3;
    this.sun.color.copy(dirColor); this.sun.intensity=dirInt;
    const p=this.player;
    this.sun.position.set(p.x-20, 20+sunY*20, p.z+10);
    this.sun.target.position.set(p.x,0,p.z);
    this.buildingMat.emissiveIntensity = clamp(1-sunY*1.5,0,1)*1.8;

    this.skyMesh.position.set(p.x,p.y,p.z);
    this.ocean.position.set(p.x-50,-0.3,p.z);
  }
  updateOcean(dt){
    const pos=this.ocean.geometry.attributes.position;
    const arr=pos.array, base=this.oceanBasePos;
    const t=this.clock.elapsedTime;
    for(let i=0;i<pos.count;i++){
      const x=base[i*3], y=base[i*3+1];
      arr[i*3+2] = Math.sin((x+y)*0.15+t*1.2)*0.25 + Math.sin(x*0.3-t*0.8)*0.15;
    }
    pos.needsUpdate=true;
    this.ocean.geometry.computeVertexNormals();
  }

  // -------------------- RESIZE / LOOP --------------------
  onResize(){
    const w=window.innerWidth, h=window.innerHeight;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio||1, QUALITY[this.quality].pixelRatio));
    this.renderer.setSize(w,h);
    this.composer.setSize(w,h);
    this.camera.aspect=w/h; this.camera.updateProjectionMatrix();
    this.hudCanvas.width=w; this.hudCanvas.height=h;
    this.bloomPass.setSize(w,h);
  }
  animate(){
    requestAnimationFrame(this.animate);
    const dt = Math.min(0.05, this.clock.getDelta());

    if(this.state==='title' || this.state==='radio' || this.state==='help' || this.state==='settings'){
      this.previewCar.rotation.y += dt*0.6;
      this.previewRenderer.render(this.previewScene, this.previewCam);
      this.renderer.render(this.scene, this.camera); // idle background render (static-ish)
      return;
    }
    if(this.state==='paused' || this.state==='gameover'){
      return;
    }
    if(this.state==='playing'){
      if(Input.pauseEdge){ this.togglePause(); return; }
      this.fillChunksAhead(false);
      this.updatePlayer(dt);
      this.updateEntities(dt);
      this.updateEnemyBullets(dt);
      this.updateSky(dt);
      this.updateOcean(dt);
      this.updateHUD();
      this.composer.render();
    }
  }
}

window.addEventListener('DOMContentLoaded', ()=>{
  new NeonPursuit();
});

