1	// ============================================================================
2	// NEON PURSUIT — main game module
3	// Sections: CONFIG, UTIL, AUDIO, INPUT, POOLS, MODELS, ROAD, SKY, VEHICLES,
4	//           WEAPONS, PARTICLES, GAMEPLAY, HUD, UI, MAIN
5	// ============================================================================
6	import * as THREE from 'three';
7	import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
8	import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
9	import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
10	import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
11	import { FilmPass } from 'three/addons/postprocessing/FilmPass.js';
12	import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
13	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
14	
15	// ============================================================================
16	// CONFIG — tweak these to change difficulty, speed, visuals
17	// ============================================================================
18	const CFG = {
19	  ROAD_WIDTH: 14,
20	  LANE_W: 3.4,
21	  CHUNK_LEN: 40,
22	  CHUNK_SEGS: 6,
23	  DRAW_CHUNKS: { low: 16, medium: 24, high: 34 },
24	  MAX_SPEED: 68,          // m/s top speed, no nitro
25	  NITRO_MAX_SPEED: 102,
26	  ACCEL: 26,
27	  BRAKE: 48,
28	  REVERSE_ACCEL: 14,
29	  DRAG: 0.993,
30	  OFFROAD_DRAG: 0.965,
31	  STEER_RATE: 2.6,        // rad/s of wheel angle change
32	  MAX_STEER: 0.55,
33	  GRIP: 9.0,
34	  DRIFT_GRIP: 3.2,
35	  DRIFT_SLIP_THRESHOLD: 0.14,
36	  NITRO_DURATION: 3.2,
37	  NITRO_REGEN_TIME: 9,
38	  GUN_COOLDOWN: 0.09,
39	  GUN_RANGE: 140,
40	  MISSILE_COOLDOWN: 0.5,
41	  MISSILE_DAMAGE: 60,
42	  BULLET_DAMAGE: 9,
43	  CIVILIAN_HIT_PENALTY_SCORE: -400,
44	  CIVILIAN_HIT_PENALTY_TIME: -6,
45	  CHECKPOINT_TIME: 14,
46	  CHECKPOINT_SPACING: 260,
47	  TIME_START: 72,
48	  PLAYER_MAX_HEALTH: 100,
49	  FORK_SPACING: 1400,
50	  FORK_ZONE_LEN: 420,
51	  FORK_DECIDE_AT: 60,      // distance into zone where branch locks
52	  ENEMY_BASE_DENSITY: 0.009,  // enemies per meter, scales with distance
53	  CIVILIAN_BASE_DENSITY: 0.015,
54	  PICKUP_SPACING: 520,
55	};
56	
57	const QUALITY = {
58	  low:    { shadows:false, bloom:0.55, particleMul:0.4, chunks:CFG.DRAW_CHUNKS.low,    pixelRatio:1.0, film:false },
59	  medium: { shadows:true,  bloom:0.8,  particleMul:0.8, chunks:CFG.DRAW_CHUNKS.medium, pixelRatio:1.3, film:true },
60	  high:   { shadows:true,  bloom:1.1,  particleMul:1.3, chunks:CFG.DRAW_CHUNKS.high,   pixelRatio:1.8, film:true },
61	};
62	
63	// Biome stage list (meters where each begins), cycles after the last
64	const STAGES = [
65	  { name:'COASTAL HIGHWAY', biome:'beach',   sky:'day',    len:1600 },
66	  { name:'SUNSET DUNES',    biome:'desert',  sky:'sunset', len:1700 },
67	  { name:'MIDNIGHT CITY',   biome:'city',    sky:'night',  len:1800 },
68	  { name:'DUSK PASS',       biome:'mountain',sky:'dusk',   len:1700 },
69	];
70	const STAGE_TOTAL_LEN = STAGES.reduce((a,s)=>a+s.len,0);
71	
72	const SKY_PALETTES = {
73	  day:   { top:0x1b6fd6, bottom:0xbfe9ff, fog:0x8fcdf2, sun:0xfff3c4, hemiSky:0xbfe9ff, hemiGround:0x3a6b3a, dirColor:0xfff6e0, dirInt:1.05, ambient:0.32, stars:0, sunY:0.62 },
74	  sunset:{ top:0x3b1458, bottom:0xff7a3d, fog:0xd97e52, sun:0xffd23f, hemiSky:0xff9a62, hemiGround:0x5a3a2a, dirColor:0xffb36b, dirInt:0.95, ambient:0.3, stars:0.3, sunY:0.22 },
75	  dusk:  { top:0x140826, bottom:0x5a2a6b, fog:0x301a3e, sun:0xff6b9a, hemiSky:0x5a2a6b, hemiGround:0x241433, dirColor:0xb87bff, dirInt:0.6, ambient:0.25, stars:0.7, sunY:0.1 },
76	  night: { top:0x05030e, bottom:0x160a2e, fog:0x0a0518, sun:0x8b2fff, hemiSky:0x1a0f33, hemiGround:0x0a0614, dirColor:0x6b8bff, dirInt:0.3, ambient:0.16, stars:1.0, sunY:-0.1 },
77	};
78	
79	// ============================================================================
80	// UTIL
81	// ============================================================================
82	const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
83	const lerp=(a,b,t)=>a+(b-a)*t;
84	const smoothstep=(a,b,t)=>{t=clamp((t-a)/(b-a),0,1);return t*t*(3-2*t);};
85	function rand(seed){ // simple deterministic PRNG (mulberry32), seed is a number
86	  let t = seed + 0x6D2B79F5;
87	  t = Math.imul(t ^ (t>>>15), t | 1);
88	  t ^= t + Math.imul(t ^ (t>>>7), t | 61);
89	  return ((t ^ (t>>>14)) >>> 0) / 4294967296;
90	}
91	let RNG_STATE = 12345;
92	function srand(){ RNG_STATE = (RNG_STATE*1664525+1013904223) >>> 0; return RNG_STATE/4294967296; }
93	function srange(a,b){ return a+(b-a)*srand(); }
94	function pick(arr){ return arr[Math.floor(srand()*arr.length)%arr.length]; }
95	
96	function stageAt(distance){
97	  let d = ((distance % STAGE_TOTAL_LEN)+STAGE_TOTAL_LEN) % STAGE_TOTAL_LEN;
98	  for(const s of STAGES){ if(d < s.len) return s; d -= s.len; }
99	  return STAGES[0];
100	}
101	function stageBlend(distance){
102	  // returns {a,b,t} interpolation between consecutive stage sky palettes for smooth transitions
103	  let d = ((distance % STAGE_TOTAL_LEN)+STAGE_TOTAL_LEN) % STAGE_TOTAL_LEN;
104	  let i=0;
105	  for(;i<STAGES.length;i++){ if(d < STAGES[i].len) break; d -= STAGES[i].len; }
106	  const cur = STAGES[i % STAGES.length];
107	  const next = STAGES[(i+1) % STAGES.length];
108	  const transition = 220;
109	  const t = d > cur.len - transition ? smoothstep(cur.len-transition, cur.len, d) : 0;
110	  return { a:cur.sky, b:next.sky, t, biome:cur.biome, name:cur.name };
111	}
112	
113	// ============================================================================
114	// AUDIO — procedural Web Audio engine
115	// ============================================================================
116	const Audio_ = (()=>{
117	  let ctx=null, master, musicGain, sfxGain, engineGain;
118	  let started=false;
119	  let engineNodes=null;
120	  let musicState=null;
121	  const stations = [
122	    { name:'OUTRUN 85', desc:'Bassline + arps, classic cruise', key:'a' },
123	    { name:'NEON PULSE', desc:'Gated drums, driving energy', key:'b' },
124	    { name:'VELVET NIGHT', desc:'Slow arpeggio, dusk mood', key:'c' },
125	  ];
126	  function init(){
127	    if(ctx) return;
128	    ctx = new (window.AudioContext||window.webkitAudioContext)();
129	    master = ctx.createGain(); master.gain.value=0.8; master.connect(ctx.destination);
130	    musicGain = ctx.createGain(); musicGain.gain.value=0.6; musicGain.connect(master);
131	    sfxGain = ctx.createGain(); sfxGain.gain.value=0.9; sfxGain.connect(master);
132	    engineGain = ctx.createGain(); engineGain.gain.value=0.5; engineGain.connect(sfxGain);
133	  }
134	  function resume(){ if(ctx && ctx.state==='suspended') ctx.resume(); started=true; }
135	  function setVol(which,v){
136	    if(!ctx) return;
137	    if(which==='master') master.gain.setTargetAtTime(v,ctx.currentTime,0.05);
138	    if(which==='music') musicGain.gain.setTargetAtTime(v,ctx.currentTime,0.05);
139	    if(which==='sfx') sfxGain.gain.setTargetAtTime(v,ctx.currentTime,0.05);
140	  }
141	  function noiseBuffer(dur=1){
142	    const n = ctx.sampleRate*dur;
143	    const buf = ctx.createBuffer(1,n,ctx.sampleRate);
144	    const d = buf.getChannelData(0);
145	    for(let i=0;i<n;i++) d[i]=Math.random()*2-1;
146	    return buf;
147	  }
148	  let noiseBuf1s=null;
149	  function getNoise(){ if(!noiseBuf1s) noiseBuf1s=noiseBuffer(1); return noiseBuf1s; }
150	
151	  // ---- SFX ----
152	  function sfxGunshot(){
153	    if(!ctx) return;
154	    const t=ctx.currentTime;
155	    const osc=ctx.createOscillator(); osc.type='square'; osc.frequency.setValueAtTime(220,t);
156	    osc.frequency.exponentialRampToValueAtTime(60,t+0.07);
157	    const g=ctx.createGain(); g.gain.setValueAtTime(0.25,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.08);
158	    const src=ctx.createBufferSource(); src.buffer=getNoise();
159	    const nf=ctx.createBiquadFilter(); nf.type='highpass'; nf.frequency.value=800;
160	    const ng=ctx.createGain(); ng.gain.setValueAtTime(0.18,t); ng.gain.exponentialRampToValueAtTime(0.001,t+0.05);
161	    osc.connect(g).connect(sfxGain); src.connect(nf).connect(ng).connect(sfxGain);
162	    osc.start(t); osc.stop(t+0.1); src.start(t); src.stop(t+0.06);
163	  }
164	  function sfxMissile(){
165	    if(!ctx) return;
166	    const t=ctx.currentTime;
167	    const osc=ctx.createOscillator(); osc.type='sawtooth'; osc.frequency.setValueAtTime(90,t);
168	    osc.frequency.exponentialRampToValueAtTime(400,t+0.4);
169	    const g=ctx.createGain(); g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(0.22,t+0.05); g.gain.exponentialRampToValueAtTime(0.001,t+0.5);
170	    osc.connect(g).connect(sfxGain); osc.start(t); osc.stop(t+0.5);
171	  }
172	  function sfxExplosion(big=false){
173	    if(!ctx) return;
174	    const t=ctx.currentTime; const dur=big?1.4:0.7;
175	    const src=ctx.createBufferSource(); src.buffer=getNoise(); src.loop=true;
176	    const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.setValueAtTime(big?1800:1100,t); f.frequency.exponentialRampToValueAtTime(60,t+dur);
177	    const g=ctx.createGain(); g.gain.setValueAtTime(big?0.5:0.32,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
178	    src.connect(f).connect(g).connect(sfxGain);
179	    src.start(t); src.stop(t+dur);
180	    duckMusic(dur);
181	  }
182	  function sfxCrash(){
183	    if(!ctx) return;
184	    const t=ctx.currentTime;
185	    const src=ctx.createBufferSource(); src.buffer=getNoise();
186	    const f=ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=500; f.Q.value=0.6;
187	    const g=ctx.createGain(); g.gain.setValueAtTime(0.4,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.3);
188	    src.connect(f).connect(g).connect(sfxGain); src.start(t); src.stop(t+0.3);
189	  }
190	  function sfxScreech(){
191	    if(!ctx) return;
192	    const t=ctx.currentTime;
193	    const osc=ctx.createOscillator(); osc.type='sawtooth'; osc.frequency.setValueAtTime(900+Math.random()*200,t);
194	    const f=ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=1800; f.Q.value=6;
195	    const g=ctx.createGain(); g.gain.setValueAtTime(0.09,t); g.gain.linearRampToValueAtTime(0.0,t+0.25);
196	    osc.connect(f).connect(g).connect(sfxGain); osc.start(t); osc.stop(t+0.25);
197	  }
198	  function sfxChime(){
199	    if(!ctx) return;
200	    const t=ctx.currentTime;
201	    [660,880,1320].forEach((f,i)=>{
202	      const osc=ctx.createOscillator(); osc.type='sine'; osc.frequency.value=f;
