243	  // ---- Engine sound: layered oscillators tracking RPM ----
244	  function engineInit(){
245	    if(!ctx || engineNodes) return;
246	    const osc1=ctx.createOscillator(); osc1.type='sawtooth';
247	    const osc2=ctx.createOscillator(); osc2.type='square';
