251	    const g2=ctx.createGain(); g2.gain.value=0.035;
252	    const gs=ctx.createGain(); gs.gain.value=0.05;
253	    osc1.connect(g1).connect(f); osc2.connect(g2).connect(f); sub.connect(gs).connect(f);
254	    f.connect(engineGain);
255	    osc1.start(); osc2.start(); sub.start();
