258	  function engineUpdate(throttle01, speed01, dt, nowSec){
259	    if(!engineNodes) return;
260	    const n=engineNodes;
261	    // simulated gear shifts: rpm within gear 0..1 maps speed ranges
262	    const gearCount=5;
263	    let gearSpeed = speed01*gearCount;
264	    let gear = Math.min(gearCount-1, Math.floor(gearSpeed));
265	    let rpm = gearSpeed - gear; // 0..1 within gear
266	    if(gear !== n.gear && nowSec - n.lastShift > 0.15){
267	      n.lastShift = nowSec; n.gear = gear;
268	    }
269	    const baseFreq = 55 + rpm*90 + gear*18;
270	    const targetFreq = baseFreq * (0.5+throttle01*0.5+0.5);
271	    n.osc1.frequency.setTargetAtTime(targetFreq, ctx.currentTime, 0.03);
272	    n.osc2.frequency.setTargetAtTime(targetFreq*2.01, ctx.currentTime, 0.03);
273	    n.sub.frequency.setTargetAtTime(targetFreq*0.5, ctx.currentTime, 0.03);
274	    n.f.frequency.setTargetAtTime(500+rpm*2200+throttle01*600, ctx.currentTime,0.05);
275	    const vol = 0.4+throttle01*0.5;
276	    engineGain.gain.setTargetAtTime(vol, ctx.currentTime, 0.08);
277	  }
