279	  // ---- Music: 3 stations, generated with simple step sequencers ----
280	  function stopMusic(){
281	    if(musicState){ musicState.stop=true; }
282	    musicState=null;
283	  }
284	  function scheduleStep(fn, stepTime, steps, startAt){
285	    let i=0;
286	    const state={stop:false};
287	    function tick(){
288	      if(state.stop) return;
289	      fn(i%steps, ctx.currentTime);
290	      i++;
291	      const id=setTimeout(tick, stepTime*1000);
292	      state._id=id;
293	    }
294	    tick();
295	    return state;
296	  }
297	  function playNote(freq,t,dur,type,vol,filterFreq){
298	    const osc=ctx.createOscillator(); osc.type=type; osc.frequency.value=freq;
299	    const g=ctx.createGain(); g.gain.setValueAtTime(0.0001,t);
300	    g.gain.exponentialRampToValueAtTime(vol,t+0.01);
301	    g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
302	    let node=osc;
303	    if(filterFreq){ const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=filterFreq; osc.connect(f); node=f; }
304	    node.connect(g).connect(musicGain);
305	    osc.start(t); osc.stop(t+dur+0.02);
306	  }
307	  function playDrum(kind,t){
308	    if(kind==='kick'){
309	      const osc=ctx.createOscillator(); osc.type='sine'; osc.frequency.setValueAtTime(130,t); osc.frequency.exponentialRampToValueAtTime(40,t+0.12);
310	      const g=ctx.createGain(); g.gain.setValueAtTime(0.45,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.18);
311	      osc.connect(g).connect(musicGain); osc.start(t); osc.stop(t+0.2);
312	    } else if(kind==='snare'){
313	      const src=ctx.createBufferSource(); src.buffer=getNoise();
314	      const f=ctx.createBiquadFilter(); f.type='highpass'; f.frequency.value=1200;
315	      const g=ctx.createGain(); g.gain.setValueAtTime(0.22,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.12);
316	      src.connect(f).connect(g).connect(musicGain); src.start(t); src.stop(t+0.12);
317	    } else if(kind==='hat'){
318	      const src=ctx.createBufferSource(); src.buffer=getNoise();
319	      const f=ctx.createBiquadFilter(); f.type='highpass'; f.frequency.value=6000;
320	      const g=ctx.createGain(); g.gain.setValueAtTime(0.08,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.04);
321	      src.connect(f).connect(g).connect(musicGain); src.start(t); src.stop(t+0.05);
322	    }
323	  }
324	  const SCALE_MIN = [220,246.94,261.63,293.66,329.63,349.23,392.00,440]; // A minor-ish
325	  function startStationA(){ // OUTRUN 85 — bassline + arp, mid tempo
326	    const bpm=118, step=60/bpm/2;
327	    const bass=[0,0,3,3,4,4,2,2];
328	    const arp=[0,4,5,7,5,4,0,2];
329	    musicState = scheduleStep((i,t)=>{
330	      playNote(SCALE_MIN[bass[i%8]]/2, t, step*1.9, 'sawtooth', 0.11, 500);
331	      playNote(SCALE_MIN[arp[i%8]], t+step*0.5, step*0.5, 'square', 0.05, 2200);
332	      if(i%4===0) playDrum('kick',t);
333	      if(i%8===4) playDrum('snare',t);
334	      if(i%2===0) playDrum('hat',t);
335	    }, step, 8);
336	  }
337	  function startStationB(){ // NEON PULSE — gated drums, driving
338	    const bpm=132, step=60/bpm/2;
339	    const bass=[0,2,0,2,3,2,0,5];
340	    musicState = scheduleStep((i,t)=>{
341	      playNote(SCALE_MIN[bass[i%8]]/2, t, step*0.9, 'square', 0.1, 700);
342	      if(i%2===0) playDrum('kick',t);
343	      playDrum('hat',t);
344	      if(i%8===6) playDrum('snare',t);
345	      if(i%16===0) playNote(SCALE_MIN[7], t, step*4, 'sawtooth', 0.06, 1400);
346	    }, step, 16);
347	  }
348	  function startStationC(){ // VELVET NIGHT — slow arpeggio, dusk mood
349	    const bpm=86, step=60/bpm/2;
350	    const arp=[0,3,5,7,8,7,5,3];
351	    musicState = scheduleStep((i,t)=>{
352	      playNote(SCALE_MIN[arp[i%8]], t, step*1.6, 'triangle', 0.09, 1800);
353	      if(i%8===0) playNote(SCALE_MIN[0]/2, t, step*6, 'sine', 0.08, 400);
354	      if(i%4===0) playDrum('hat',t);
355	    }, step, 8);
356	  }
357	  function playStation(idx){
358	    stopMusic();
359	    if(!ctx) return;
360	    if(idx===0) startStationA();
361	    else if(idx===1) startStationB();
362	    else startStationC();
363	  }
364	  return {
365	    init, resume, setVol, stations, playStation, stopMusic,
366	    sfxGunshot, sfxMissile, sfxExplosion, sfxCrash, sfxScreech, sfxChime, sfxBeepWarn, sfxPickup,
367	    heliStart, heliSet, heliStop, engineInit, engineUpdate,
368	    get ctx(){ return ctx; }
