456	// Simple pooled particle system using sprite planes on one InstancedMesh per type
457	class ParticleSystem{
458	  constructor(scene, maxCount, color, opts={}){
459	    const geo = new THREE.PlaneGeometry(1,1);
460	    const mat = new THREE.MeshBasicMaterial({ color, transparent:true, opacity:1, depthWrite:false, blending: opts.additive!==false? THREE.AdditiveBlending: THREE.NormalBlending, side:THREE.DoubleSide });
461	    this.mesh = new THREE.InstancedMesh(geo, mat, maxCount);
462	    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
463	    this.mesh.frustumCulled=false;
464	    this.mesh.count = maxCount;
465	    this.colorAttr = new Float32Array(maxCount*3);
466	    this.mesh.instanceColor = new THREE.InstancedBufferAttribute(this.colorAttr,3);
467	    scene.add(this.mesh);
468	    this.max=maxCount;
469	    this.particles = new Array(maxCount).fill(null).map(()=>({active:false,pos:new THREE.Vector3(),vel:new THREE.Vector3(),life:0,maxLife:1,size:1,growth:0,rotSpeed:0,rot:0, colorStart:new THREE.Color(color), colorEnd:new THREE.Color(color), gravity:0}));
470	    this._dummy = new THREE.Object3D();
471	    this._cursor=0;
472	  }
473	  spawn(pos,vel,life,size,opts={}){
474	    const p = this.particles[this._cursor];
475	    this._cursor = (this._cursor+1)%this.max;
476	    p.active=true; p.pos.copy(pos); p.vel.copy(vel); p.life=life; p.maxLife=life; p.size=size;
477	    p.growth = opts.growth||0; p.rotSpeed = opts.rotSpeed||(Math.random()-0.5)*2;
478	    p.rot = Math.random()*Math.PI;
479	    p.gravity = opts.gravity||0;
480	    if(opts.colorStart) p.colorStart.copy(opts.colorStart);
481	    if(opts.colorEnd) p.colorEnd.copy(opts.colorEnd);
482	    p.fadeOut = opts.fadeOut!==false;
483	    return p;
484	  }
485	  update(dt){
486	    for(let i=0;i<this.max;i++){
487	      const p=this.particles[i];
488	      if(!p.active) continue;
489	      p.life -= dt;
490	      if(p.life<=0){ p.active=false; this._dummy.scale.set(0,0,0); this._dummy.updateMatrix(); this.mesh.setMatrixAt(i,this._dummy.matrix); continue; }
491	      p.vel.y -= p.gravity*dt;
492	      p.pos.addScaledVector(p.vel,dt);
493	      p.rot += p.rotSpeed*dt;
494	      const t = 1 - p.life/p.maxLife;
495	      const sz = p.size + p.growth*t;
496	      const d=this._dummy;
497	      d.position.copy(p.pos); d.rotation.set(0,0,p.rot); d.scale.set(sz,sz,sz);
498	      d.updateMatrix();
499	      this.mesh.setMatrixAt(i,d.matrix);
500	      const c = p.colorStart.clone().lerp(p.colorEnd, t);
501	      this.mesh.setColorAt(i,c);
502	      if(this.mesh.material.opacity!==undefined){ /* handled via color brightness */ }
503	    }
504	    this.mesh.instanceMatrix.needsUpdate=true;
505	    if(this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate=true;
506	  }
507	}
