521	    for(let i=0;i<count;i++){ colors[i*3]=c.r; colors[i*3+1]=c.g; colors[i*3+2]=c.b; }
522	    g.setAttribute('color', new THREE.BufferAttribute(colors,3));
523	    geos.push(g);
524	  }
525	  return mergeGeometries(geos,false);
526	}
