801	        varying vec3 vPos; uniform vec3 topColor,bottomColor,sunColor; uniform float sunY,sunX,starAmount,time;
802	        float hash(vec3 p){ return fract(sin(dot(p,vec3(12.9898,78.233,37.719)))*43758.5453); }
