// MODELS — procedural low-poly vehicles & props
// ============================================================================
function mergeColored(parts){
  // parts: [{geo, color}] -> merged BufferGeometry with vertex colors
  const geos=[];
  for(const p of parts){
    const g = p.geo.clone();
    g.applyMatrix4(p.matrix||new THREE.Matrix4());
    const count = g.attributes.position.count;
    const colors = new Float32Array(count*3);
    const c = new THREE.Color(p.color);
    for(let i=0;i<count;i++){ colors[i*3]=c.r; colors[i*3+1]=c.g; colors[i*3+2]=c.b; }
    g.setAttribute('color', new THREE.BufferAttribute(colors,3));
    geos.push(g);
  }
  return mergeGeometries(geos,false);
}
const mat4=(x=0,y=0,z=0,rx=0,ry=0,rz=0,sx=1,sy=1,sz=1)=>{
  const m=new THREE.Matrix4();
  const q=new THREE.Quaternion().setFromEuler(new THREE.Euler(rx,ry,rz));
  m.compose(new THREE.Vector3(x,y,z), q, new THREE.Vector3(sx,sy,sz));
  return m;
};

function buildCarBody(bodyColor, cabinColor){
  const group = new THREE.Group();
  const bodyMat = new THREE.MeshStandardMaterial({ color:bodyColor, metalness:0.5, roughness:0.35 });
  const cabinMat = new THREE.MeshStandardMaterial({ color:cabinColor, metalness:0.2, roughness:0.5, transparent:true, opacity:0.85 });
  const darkMat = new THREE.MeshStandardMaterial({ color:0x111319, metalness:0.3, roughness:0.6 });

  const chassis = new THREE.Mesh(new THREE.BoxGeometry(2.0,0.45,4.3), bodyMat);
  chassis.position.y=0.5; chassis.castShadow=true; chassis.receiveShadow=true;
  group.add(chassis);

  const hood = new THREE.Mesh(new THREE.BoxGeometry(1.85,0.3,1.5), bodyMat);
